quests[9998] = { id = 9998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unruly Neighbors", description = "The recent arrival of the fel orcs at the ruins to the east both puzzles and troubles Thander. They wasted no time in starting to construct fortifications and repair the buildings.\n\nThe construction goes on day and night, {name}. I've dispatched one of my most reliable agents to keep watch, but we can ill afford to delay action. Move against their workers, then seek out Theloria Shadecloak at the Allerian Post to the north of the Bonechewer Ruins. She'll give you further instructions.", sourceObjective = "Kill 12 Warped Peons and then report to Theloria Shadecloak at Allerian Post.", progress = "I take it Bertelm sent you to hamper the efforts of their peons?", completion = "<The high elf nods.>\n\nIt's a good start, but Bertelm was right to send you to me. I've made a discovery that may help explain the fel orc presence here.", sourceObjectiveStatus = "unverified-source-field" }
quests[9999] = { id = 9999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Time", description = "As long as the transporters stand, nothing we do to the forge camps will have any permanence. We must find a way to destroy the Legion structures.\n\nI need time to devise a plan of attack. If you can keep their engineers and tinkerers busy, it would greatly slow down their progress, buying me the time I need.\n\nStay as far away as possible from the overseers, {name}. They are extremely dangerous beings.", sourceObjective = "Altruis the Sufferer in western Nagrand has asked that you kill 2 Felguard Legionnaires, 3 Mo'arg Engineers and 8 Gan'arg Tinkerers.", progress = "Back so soon?", completion = "It is as I suspected. There are no conventional means of destroying fel steel. All is not lost, however...", sourceObjectiveStatus = "unverified-source-field" }
quests[10000] = { id = 10000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Presence", description = "Our forces at Thrallmar thought they had the fel orcs contained in the Hellfire Citadel area, but the recent arrivals at the ruins to the east say otherwise.\n\nWe can't permit them to gain a foothold here. Rokag has dispatched Shadowstalker Kaide to the ruins to keep an eye on them, but we have to do something to keep them from digging in.\n\nGo to the ruins, decimate their peons, and then look for Kaide in the trees to the north. He'll tell you where to go from there.", sourceObjective = "Kill 12 Warped Peons and then report to Shadowstalker Kaide.", progress = "I was about to send a message back to Rokag recommending an attack, but I see that won't be necessary.", completion = "Stopping the fel orcs is going to take more than merely harassing their workers, I'm afraid. I've made a discovery that's shed some light on the reason for their presence here and it's reinforced my belief that we must act quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[10001] = { id = 10001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Planner", description = "All forge camps have a master planner. The master planner dictates what types of structures are present at a forge camp and how each structure is situated. Moreover, this information is kept on a set of blueprints that the planner carries around on their person.\n\nWe need the master planner's blueprints. Armed with such exacting information, we could persuade an acquaintance of mine to lend some assistance.\n\nFind the mo'arg master planner and take his blueprints. He will be stationed behind the forges.", sourceObjective = "Altruis the Sufferer in western Nagrand has asked that you recover the Master Planner's Blueprints.", progress = "Avoid the overseers at all costs. They must not be let on to your presence. The results could be disastrous!", completion = "My acquaintance will hopefully know of a way to destroy the camps. He was a Legion engineer, after all...", sourceObjectiveStatus = "unverified-source-field" }
quests[10002] = { id = 10002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.", sourceObjective = "Locate and slay Lisaile Fireweaver, then return to Theloria Shadecloak.", completion = "<Theloria nods at you.>\n\nWell done. We have bought ourselves a little time. The blood elves will grow curious about what happened to their friend. Hopefully, by that time, we will have a better understanding of their intentions.", sourceObjectiveStatus = "unverified-source-field" }
quests[10003] = { id = 10003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.", sourceObjective = "Locate and slay Lisaile Fireweaver, then return to Shadowstalker Kaide.", completion = "<Kaide nods at you.>\n\nWell done. We have bought ourselves a little time. The blood elves will grow curious about what happened to their friend. Hopefully, by that time, we will have a better understanding of their intentions.\n\nWhen the time is right, I will inform Rogak of our progress.", sourceObjectiveStatus = "unverified-source-field" }
quests[10004] = { id = 10004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patience and Understanding", description = "Take the blueprints and travel to Shattrath City in the Terokkar forest. Once at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim. He'll probably be at the bar, drinking away his sorrows.\n\nBy the way, you may need to convince him to lend his assistance. Try to approach him with patience and understanding. If that does not work, use your fists.", sourceObjective = "Altruis the Sufferer in western Nagrand wants you to take the Master Planner's Blueprints to Sal'salabim in Shattrath City and convince him to help you.", progress = "<Sal'salabim rubs his head.>\n\n[Demonic] Ik il romath sardon.", completion = "Calm down, bright eyes! Sal'salabim will help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10005] = { id = 10005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letting Earthbinder Tavgren Know", description = "{name}, after you're done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", sourceObjective = "Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.", completion = "A bomb utilizing pure mana that can take out whole towns!  But why?  Why would the blood elves create such a thing and use it on us?  The Cenarion Thicket was a place of peace and repose.\n\nWhatever the reason, it must be locked inside the head of Warden Treelos, and I have no idea how to cure him.  Perhaps his mind will heal in time?\n\nRegardless, I want to thank you for helping me to figure out what happened.  I can only hope that this tragedy will never befall anyone else ever again!", sourceObjectiveStatus = "unverified-source-field" }
quests[10006] = { id = 10006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letting Earthbinder Tavgren Know", description = "{name}, I think that after you're done celebrating here, you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", sourceObjective = "Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.", completion = "A bomb utilizing pure mana that can take out whole towns!  But why?  Why would the blood elves create such a thing and use it on us?  The Cenarion Thicket was a place of peace and repose.\n\nWhatever the reason, it must be locked inside the head of Warden Treelos, and I have no idea how to cure him.  Perhaps his mind will heal in time?\n\nRegardless, I want to thank you for helping me to figure out what happened.  I can only hope that this tragedy will never befall anyone else ever again!", sourceObjectiveStatus = "unverified-source-field" }
quests[10007] = { id = 10007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Ranks", description = "Knowing Thander and Bertelm, they won't tolerate such a large buildup of hostile forces on our doorstep. Asking them to dispatch members of the garrison to participate in an attack on the camp isn't an option either. It would just leave us too vulnerable to attack.\n\nIt falls to us to do what we can to diminish the threat the fel orc buildup poses. Kill what you can of their forces and I will look for ways to stall any reinforcements.", sourceObjective = "Kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers and return to Theloria Shadecloak.", progress = "Was your attack successful?", completion = "Things are starting to look up. I think if we can prevent the fel orcs from reinforcing their fellows here, we can keep this post under control.", sourceObjectiveStatus = "unverified-source-field" }
quests[10008] = { id = 10008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Happens in Terokkar Stays in Terokkar", description = "If word reaches Thrallmar that they've failed to contain the fel orcs, we're going to be receiving a lot of company down here. Frankly, I'm not sure I want all that attention, so we're going to keep this little problem under wraps, got it?\n\nIf we can inflict enough casualties on the fel orcs, chances are their presence will never come to the attention of anyone outside Stonebreaker. So, let's end it now.\n\nWade in there, swing your weapon, wave your hands, or whatever it is you do - just kill fel orcs.", sourceObjective = "Shadowstalker Kaide wants you to kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers.", progress = "Tell me I wasn't wrong to trust you with this mission...", completion = "I know you're well-traveled, but understand, {name}, that some stories are best left where they happened. Do we understand each other?", sourceObjectiveStatus = "unverified-source-field" }
quests[10009] = { id = 10009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crackin' Some Skulls", description = "<Sal'salabim laughs.>\n\nThis Sal'salabim design.\n\n<Sal'salabim points to the architecture and formations on the blueprints.>\n\nLook at towers. Demon hunter no can see, yes? Poor, poor Altruis. He cry if he had eyes, yes?\n\nYes, Sal'salabim help but first you help Sal'salabim.\n\n<Sal'salabim gives you a ledger.>\n\nThese creatures owe Sal'salabim golds. Many golds. Go collect for Sal'salabim and come back. They no give you Sal'salabim gold easy. Have to fight, but you strong. You defeat Sal'salabim!", sourceObjective = "Sal'salabim at Shattrath City wants you to recover Raliq's Debt, Coosh'coosh's Debt and Floon's Debt.", progress = "You no come back without Sal'salabim golds!", completion = "Now, deal is deal but when Sal'salabim tell you, you not be mad, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[10010] = { id = 10010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Just That Easy?", description = "<Sal'salabim points to the blueprint.>\n\nYou see where fel cannons are?\n\n<Sal'salabim draws an arrow denoting a change of direction.>\n\nYou turn fel cannon around and use on structures.\n\nWait! Don't be mad! One thing you not know. Overseers have key to turn cannons. You need key first! One from each overseer!\n\nNot so easy, eh?\n\nTake information back to Altruis.", sourceObjective = "Sal'salabim at Shattrath City wants you to return to Altruis the Sufferer in western Nagrand.", completion = "Of course! We will use their own weapons against them!", sourceObjectiveStatus = "unverified-source-field" }
quests[10011] = { id = 10011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camp: Annihilated", description = "Gather your allies, {name}. You will need them if you are to face an overseer.\n\nOnce you have a suitable group, find and kill the overseers at each camp. Take their keys and use them to turn and fire the fel cannons upon the camps. Return to me once the camps are destroyed.", sourceObjective = "Altruis the Sufferer in western Nagrand has asked that you Destroy Forge Camp: Hate and Destroy Forge Camp: Fear.", progress = "Is it done?", completion = "We are victorious! The Legion's advances have been halted!\n\nI offer you a choice of rewards for your heroic deeds!", sourceObjectiveStatus = "unverified-source-field" }
quests[10012] = { id = 10012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Orc Plans", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Bertelm might have some insight into this odd alliance. You decide to make your way back to the Allerian Stronghold and show him the map.", sourceObjective = "Bring the Fel Orc Plans to Bertelm at the Allerian Stronghold.", progress = "What is it you have there, {name}?", completion = "<Bertelm takes the plans from you and looks them over.>\n\nIf you hadn't brought this map, I'd say you were out of your mind, but here it is, plain as day. Not only are the fel orcs here to serve the blood elves, but it appears, they've been ordered to keep us occupied.\n\nThis map raises more questions than it answers, but it gives us a better idea of what we're facing here.", sourceObjectiveStatus = "unverified-source-field" }
quests[10013] = { id = 10013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unseen Hand", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Rokag might have some insight into this odd alliance. You decide to make your way back to Stonebreaker Hold and show him the map.", sourceObjective = "Bring the Fel Orc Plans to Rokag at Stonebreaker Hold.", progress = "What is it you have there, {name}?", completion = "<Rokag takes the plans from you and looks them over.>\n\nSo Kaide was right! Those fel orc scum are up to something. I never would've guessed they were colluding with the blood elves, though.\n\nAccording to this map, the fel orcs are to keep us busy... but why? This is disturbing news, {name}. You were correct in bringing it to me right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[10014] = { id = 10014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Point Project", description = "As I was saying, we've just received some further intel and there's a much larger problem at hand.\n\nThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on the Allerian Stronghold!\n\nMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!", sourceObjective = "Steal the four Mana Bomb Code Sheets and deliver them to Lieutenant Meridian at the Allerian Post in Terokkar Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10015] = { id = 10015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firewing Point Project", description = "As I was saying, we've just received some further intel and there's a much larger problem at hand.\n\nThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on Stonebreaker Hold!\n\nMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!", sourceObjective = "Steal the four Mana Bomb Code Sheets and deliver them to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10016] = { id = 10016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timber Worg Tails", description = "Have you come across the timber worgs in your travels? I've had the opportunity to observe them while mapping some of the northern reaches of the forest. I wouldn't recommend getting close to them unless you're prepared for combat.\n\nThey have no fear of us and won't hesitate to defend their territory.\n\nIt's fitting that such a creature would have a magnificent tail. I've been trying to collect enough of them to trim a new cloak, but the worgs have a habit of evading my snares. Will you help?", sourceObjective = "Bertelm at the Allerian Stronghold wants you to bring him 12 Timber Worg Tails. The tails can come from either Timber Worgs or Timber Worg Alphas.", progress = "I see you've managed to survive the rigors of the forest. Have you brought any tails for my cloak?", completion = "Ah, well done, friend. These are finer than I thought they'd be. They'll make a fine cloak.\n\n<Bertelm glances toward the inn.>\n\nYes, a fine cloak it shall be.", sourceObjectiveStatus = "unverified-source-field" }
quests[10017] = { id = 10017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strained Supplies", description = "More and more refugees come through the gates of Shattrath City each day.  Some have sustained such injuries, it's a real wonder they made it here.\n\nI can deal with most of the conventional injuries; my training as an Aldor healer has prepared me for that.  Poison wounds are more problematic as my anti-venom supplies have begun to run low.\n\nBring me venom sacs from the local dreadfang spiders so I can produce more antidotes.  You'll find a pocket of the spiders in the southeastern region of Terokkar.", sourceObjective = "Bring 8 Dreadfang Venom Sacs to Sha'nir in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you obtained the venom sacs, {name}?  These refugees can't wait much longer.", completion = "You have my thanks, {name}.  The Aldor will hear of your actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[10018] = { id = 10018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vestments of the Wolf Spirit", description = "Generations ago, when orc clans still called Terokkar Forest home, the wolf spirit played an important role in their lives. When the orcs departed, they had no longer had any need for the spirit and they left it behind.\n\nIn time, the spirit grew lonely and it too left the forest.\n\nI believe I can bring the wolf spirit back to his ancestral home, just as we orcs have returned. The ritual will require me to create vestments from the pelts of the wolves of the forest to guide the spirit back to its home.", sourceObjective = "Bring 12 Timber Worg Pelts to Malukaz at Stonebreaker Hold.", progress = "Were you able to find all the pelts that I need?", completion = "These are perfect, {name}! I could not have asked for better.", sourceObjectiveStatus = "unverified-source-field" }
quests[10019] = { id = 10019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Venom Sacs", progress = "Many refugees still need treatment for their poisonous wounds.  Have you brought more venom sacs for me to use, {name}?", completion = "You have my thanks, {name}.  The naaru have extended their protection to these unfortunate souls; it would be a shame if they made it to Shattrath and perished to previous wounds." }
quests[10020] = { id = 10020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cure for Zahlia", description = "The woman to my right suffered a severe injury to the head.  She survived, but lost her eyesight.\n\nA traditional cure used among my people requires the blood of a very old basilisk.\n\nUnfortunately, due to poaching from various groups, Terokkar basilisks don't tend to live very long.\n\nThere is one basilisk whose name I've known since I was a youngling.  It is known only as \"Stonegazer\" and it's rumored to live east of here, near the land's edge.\n\nBring me its blood so that Zahlia may see once again.", sourceObjective = "Bring Stonegazer's Blood to Sha'nir in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you obtained the blood, {name}?  Without it, Zahlia may never see her son again.", completion = "Thank you, {name}.  Caring for those in need is a difficult task, but in time I've discovered that it is its own reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10021] = { id = 10021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring the Light", description = "Much of this region was inhabited by draenei long ago.  We Aldor were charged with the safeguarding of our holy sites and altars.  Many of them have since been destroyed or taken over by our enemies.\n\nTo the east of here there is an arakkoa outpost.  It was purposefully built on the location of three of our sacred altars. The arakkoa use their foul magic to warp and defile the innate power of our shrines.\n\nTake this to the arakkoa outpost and use it to cleanse the three altars.", sourceObjective = "Ishanah wants you to go to the Arakkoa outpost east of Shattrath City and use the Blessed Vial to cleanse the Eastern Altar, the Western Altar and the Northern Altar.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed your task, {name}?", completion = "You have my thanks, {name}.  We are keepers of the light and cannot forsake our responsibilities, even in the most difficult of times.", sourceObjectiveStatus = "unverified-source-field" }
quests[10022] = { id = 10022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elusive Ironjaw", description = "Now that I have the fur I'll need for the trim, I've been thinking that the pelt of a particular wolf would make a good hood for my cloak. Imagine seeing your enemy clad in the pelt of the most cunning predator in the forest!\n\nI've tried trapping old Ironjaw without success. I've tried cornering him, outsmarting him, and baiting him. None of it has worked.\n\nHe stalks the northeastern reaches of the forest, and I'd gladly reward you if you could succeed where I have failed.", sourceObjective = "Bring Ironjaw's Pelt to Bertelm at the Allerian Stronghold.", progress = "Has old Ironjaw gotten the better of you, too, friend? Or have you managed to outsmart the old fellow?", completion = "I bow to your skills, {name}. You have proven yourself the superior hunter.\n\nI won't forget your help in making this cloak. It will truly be a one-of-a-kind piece and I'll wear it proudly.", sourceObjectiveStatus = "unverified-source-field" }
quests[10023] = { id = 10023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patriarch Ironjaw", description = "You've done well in gathering the first pelts.\n\nThe final piece of the vestments requires a pelt unlike any other. There is one particular wolf, an old and cunning one, that has earned his place as the patriarch of the forest wolves. He is known among them as Ironjaw, the mighty hunter.\n\nIn my visions, I have seen him wandering the northeastern region of the forest. Including his pelt in the vestments will surely light the wolf spirit's path.\n\nDo not mourn Ironjaw. He will be well honored.", sourceObjective = "Bring Ironjaw's Pelt to Malukaz at Stonebreaker Hold.", progress = "The spirit awaits, {name}. Have you the pelt of the wolf patriarch?", completion = "The pelt is even more magnificent than I had hoped! This is a good omen, {name}, and the spirits will favor you for your contribution to this ceremony.\n\nI have fashioned a helmet for you from the remaining pelts, {name}. It identifies you as a mighty hunter and an ally of the great wolf spirit of Terokkar Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10024] = { id = 10024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voren'thal's Visions", description = "Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas.  His prophetic visions warned him that Kael's path would lead to the destruction of our race.\n\nThe visions are usually vague and unfocused, but our alchemists have devised an elixir to help him focus his clairvoyance.  Unfortunately, this elixir calls for a rare ingredient: basilisk eyes.  My usual source, this pathetic ethereal, has failed me.\n\nSeek the dampscale basilisks in the rocky regions of Terokkar and bring me their eyes.", sourceObjective = "Bring 8 Dampscale Basilisk Eyes to Arcanist Adyria in Shattrath City.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you obtained the basilisk eyes for Voren'thal's elixir?", completion = "These are all in excellent state, {name}.  Carry on and you will soon count the Scryers as your friends.", sourceObjectiveStatus = "unverified-source-field" }
quests[10025] = { id = 10025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Basilisk Eyes", progress = "It takes many basilisk eyes to make even a small dose of Voren'thal's elixir.  Bringing me more would certainly incur the Scryers' favor.", completion = "I thank you, {name}.  Voren'thal's visions might one day decide the fate of our race.  It would behoove us to do our best to ensure that those visions are as accurate as possible." }
quests[10026] = { id = 10026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Disturbances", description = "It's embarrassing to admit this, but something has happened to me here in Terokkar Forest that hasn't occurred since my apprentice days.\n\nOccasionally, my spells will fizzle when I know I've done everything correctly. I almost drove myself crazy the first time it happened.\n\nI think I've found the cause. The forest is full of creatures called warp stalkers, demonic creatures with an affinity for magic and a habit of disturbing magical flows. The best way to deal with them is simply to kill them.", sourceObjective = "Andarl at the Allerian Stronghold wants you to kill 10 Warp Stalkers.", completion = "<Andarl dabs at his forehead with the sleeve of his robe.>\n\nThank goodness. I was beginning to wonder if the things had displaced the rest of the forest's creatures.", sourceObjectiveStatus = "unverified-source-field" }
quests[10027] = { id = 10027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Disturbances", description = "There's nothing more annoying than preparing to cast a spell, only to have it interrupted by some unseen force. After the fourth time, I knew it couldn't be coincidence and I sent Keb'ezil out to investigate.\n\nI guarantee you'll never encounter an imp that talks back more than Keb.\n\nAnyway, he managed to find the source of the problem, a pesky creature known as a warp stalker. They have a habit of disturbing the magical energy wherever they blink into existence. I've had enough of their interference.", sourceObjective = "Kill 10 Warp Stalkers and return to Kurgatok at Stonebreaker Hold.", completion = "Keb'ezil is relieved that you've taken care of that little problem, aren't you, Keb?\n\n<The imp ignores its master, presumably out of indignation.>\n\nYou'll have to forgive his bad manners. You know how demons can be...", sourceObjectiveStatus = "unverified-source-field" }
quests[10028] = { id = 10028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vessels of Power", description = "Amid the ruins of Tuurem are a number of vessels containing raw, magical energy. We are fortunate that the Broken who have overrun the city are ignorant to the resource in their midst, but we cannot assume they will remain so forever.\n\nWith those vessels and their power in hand, the scattered survivors of my people can resist the lure of demonic magic. Every quel'dorei we can save from our prince's folly is one more that can help us regain our lost glory. Bring me these vessels, {class}.", sourceObjective = "Bring 8 Draenei Vessels to Ros'eleth at the Allerian Stronghold.", progress = "Were you able to find any intact vessels?", completion = "I hope these aren't the only intact vessels in the city. This is a good start, but I suspect we'll need many more than this.", sourceObjectiveStatus = "unverified-source-field" }
quests[10029] = { id = 10029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits Are Calling", description = "The spirits of the dead in the Bone Wastes have been calling out to me and they are in pain!\n\n{class}, you must journey to the Bone Wastes to the south and find my assistant, Soolaveen with the Refugee Caravan.  He must be feeling it too, and will need your assistance to help put the spirits there to rest.\n\nIf you hurry, you may catch them.  I know that they were going to stop for a while in the northern portion of the Bone Wastes before continuing south to Auchindoun.", sourceObjective = "Anchorite Lyteera wants you to locate her assistant, Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[10030] = { id = 10030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Bones", description = "The bones of the dead draenei litter the Bone Wastes from the explosion of Auchindoun.  Their spirits are restless, and cannot move on to the next life.\n\n{class}, you must help me to recover their bones and take them to their final resting place!  Only then will they be at peace; only then will they know comfort.\n\nGather up the restless bones with care and deliver them to Ramdor the Mad at Auchindoun in the center of the Bone Wastes.  Despite his name, he will know how to care for them.", sourceObjective = "Collect 10 Restless Bones. Deliver them to Ramdor the Mad, just off the western side of the Ring of Observance in Auchindoun, which is in the middle of the Bone Wastes of Terokkar Forest.", progress = "What's this?  Who are you?", completion = "Great, just what I needed... more bones.\n\n<Ramdor sighs.>\n\nYes, yes, I will see to it that these remains of our honored ancestors are given a proper burial, have no fear.\n\nThere is something else that you can do if you're truly interested in aiding the dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[10031] = { id = 10031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Lost Find Their Way", description = "Many spirits of the draenei were corrupted by the explosion of Auchindoun.  Now they wander the wastes in torment.\n\n{name}, I beseech you to put them to rest.  Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's walls.\n\nWhat?  You think leaving them to wander in blind agony would be better?\n\nAfterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.", sourceObjective = "Destroy 10 Lost Spirits and 10 Broken Skeletons, and then speak with Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.", progress = "{name}?  What brings you back to me?  Did you deliver the bones of the restless to Ramdor as I requested?", completion = "You have done that which needed doing and there is nothing to forgive.  Though it saddens me to hear that they were corrupted into a horrible undeath, through your actions you have put them to rest.\n\nThank you for setting them free, {name}.  You must accept a humble token of my regard for you and your selflessness.", sourceObjectiveStatus = "unverified-source-field" }
quests[10032] = { id = 10032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts from Tuurem", description = "Have you ever noticed the behavior of the Lost Ones in Tuurem? They wander the ruins, searching for surviving scraps of anything made by the draenei.\n\nTheir Broken masters know better. They've left their former lives and identities behind and become something completely different.\n\nI believe we can use the Lost Ones' compulsion to our benefit and gather old draenei relics from them. Why risk life and limb battling the Broken, when we can profit from picking our targets wisely?", sourceObjective = "Gather 6 Tuurem Artifacts from Tuurem Scavengers and Tuurem Hunters and bring them to Rakoria at Stonebreaker Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10033] = { id = 10033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Bonelashers Dead!", description = "A bounty is declared on the bonelashers of the Bone Wastes.  As known carriers of the plague, they are to be destroyed forthwith!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReport to Taela Everstride afterward to collect your reward.", sourceObjective = "Kill 20 Bonelashers and then report to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", completion = "Yeah, I'm sure that you killed all of those bonelashers.  It's obvious since the captain asked for you to turn in proof on that wanted poster.\n\n<Taela gives you a sarcastic look.>\n\nI'll take your word for it.  I'm not certain who I angered to pull this duty, but thanks for your efforts on behalf of the Alliance.  Here's a little something for all of your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[10034] = { id = 10034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Bonelashers Dead!", description = "The bonelashers of the Bone Wastes bit Mawg and made him sick.  Now he wants all of them destroyed!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReturn to Mawg Grimshot after you've done the deed and he'll give you a good reward.", sourceObjective = "Kill 20 Bonelashers and then report to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", progress = "Is that bonelasher blood on your hands that I smell?", completion = "You must have killed a lot of those bonelashers!  Good, I hate them!  Ever since I was bit by one of them, I keep having fainting spells.\n\nDo you realize how embarrassing that is?  Here, take this as thanks for exacting some revenge for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10035] = { id = 10035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him.\n\nI speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes.\n\nToo bad that there's an arakkoan scarecrow there, known as Torgos's Bane, which keeps him at bay.  I'd bet if you laid his mate Trachela's carcass at the foot of that scarecrow he'd come down anyway.  She can be found at Carrion Hill in the northern wastes.\n\nBring me one of Torgos's tail feathers.", sourceObjective = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", progress = "You have the feather?  Am I to reward you for your foolhardy bravery?", completion = "Color me impressed, {class}.  Torgos was one of the toughest creatures I know of this side of Nagrand.\n\nWell, I suppose that's good enough for something from the Allerian Stronghold treasury.  Take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[10036] = { id = 10036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "I want Torgos, king of the bonelashers, dead!\n\nNot long ago, while I was out hunting at Veil Rhaze on the western edge of the wastes, he fell upon me.\n\n<Mawg taps his eyepatch.>\n\nHe took my eye, and now I would have his life!  Bring me one of his tail feathers as proof and I'll give you a worthy reward.\n\nYou'll need his mate Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan scarecrow known as Torgos's Bane.\n\nFind her at Carrion Hill in the northern wastes.", sourceObjective = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", progress = "Did you kill him?  Is Torgos dead?!\n\nYou have proof?", completion = "I thank you, {name}!  You have exacted my revenge, and as promised you will be rewarded!\n\nTake your pick of one of these and use it well!", sourceObjectiveStatus = "unverified-source-field" }
quests[10037] = { id = 10037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rather Be Fishin'", description = "Speaking of lakes, there's a lake with real good fishin' up to the northeast. I used to go up there with my friends, but my mom won't let me go anymore.\n\nShe says it's too dangerous, but I haven't seen anything up there but a few little spiders. Like spiders can do anything to you...\n\nMy favorites were always the eels that live up there. If you're going to be up by the lake, would you think about bringing back some of the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.", sourceObjective = "Bring 8 Pristine Shimmerscale Eels to Seth in Shattrath.", progress = "<Seth tugs on your cloak.>\n\nDid you find the eels? Didja?", completion = "Thanks! I can't remember the last time I had eel!\n\nHow should I cook 'em?", sourceObjectiveStatus = "unverified-source-field" }
quests[10038] = { id = 10038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Private Weeks", description = "A report's just come in from one of our scouts near Grangol'var Village.  He says that a shadowy band has moved into the ruins there.\n\n{name}, I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to.  Just head west past Stonebreaker Hold.  His last report puts his position near the north entrance to the village.", sourceObjective = "Locate and speak with Private Weeks near the north entrance to Grangol'var Village in Terokkar Forest.", completion = "It's about time someone came out here.  I sent that report to the Allerian Stronghold over a week ago!\n\nBureaucracy!", sourceObjectiveStatus = "unverified-source-field" }
quests[10039] = { id = 10039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Scout Neftis", description = "I am informed that one of our scouts near Grangol'var Village is currently observing a shadowy band that has recently moved in there.\n\n{name}, I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to.\n\nJust head south out of here, and then due west, skirting the north of the Bone Wastes.  Her last report puts her position near the southern entrance to the village.", sourceObjective = "Locate and speak with Scout Neftis near the south entrance to Grangol'var Village in Terokkar Forest.", completion = "It's about time someone came out here.  I sent that report to Stonebreaker Hold over a week ago!\n\nBlood elves and their bureaucracy!", sourceObjectiveStatus = "unverified-source-field" }
quests[10040] = { id = 10040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", sourceObjective = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Private Weeks at Grangol'var Village in Terokkar Forest.", progress = "You speak with all of them yet?  What did they have to say?", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?", sourceObjectiveStatus = "unverified-source-field" }
quests[10041] = { id = 10041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", sourceObjective = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Scout Neftis at Grangol'var Village in Terokkar Forest.", progress = "You speak with all of them yet?  What did they have to say?", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?", sourceObjectiveStatus = "unverified-source-field" }
quests[10042] = { id = 10042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold.\n\nGood luck, {class}!", sourceObjective = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Lieutenant Gravelhammer at the Allerian Stronghold in Terokkar Forest.", completion = "That's dire news indeed!  Well, it would seem I made the right choice in sending you out there to help Weeks.  The last thing that we want is the Shadow Council establishing themselves right on our doorstep!\n\n{name}, in recognition of your efforts at Grangol'var Village, I hereby grant you the right to your pick of any of these fine rewards.", sourceObjectiveStatus = "unverified-source-field" }
quests[10043] = { id = 10043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Advisor Faila at Stonebreaker Hold.\n\nGood luck, {class}!", sourceObjective = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", completion = "That is unfortunate news!  But, of course, I made the right choice in sending you out there to help Neftis.  The last thing that we need is the Shadow Council establishing a strong point right on our doorstep!\n\n{name}, you've earned yourself something nice.  Go ahead, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[10044] = { id = 10044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit With the Greatmother", description = "The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once.\n\nMy will has been sapped but make no mistake, {name}, if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall.\n\n<Garrosh points at the large building to the north.>\n\nListen to what she has to say and do as she tells you.", sourceObjective = "Speak to Greatmother Geyah and listen to what she has to tell you.", progress = "Please, sit down, dear.", completion = "We must first expand your mind so that you may commune with the ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[10045] = { id = 10045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Material Components", description = "Mother Kashur wishes to speak with you, {name}. Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits.\n\nYou must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade's Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.", sourceObjective = "Greatmother Geyah at Garadar in Nagrand has asked that you collect 1 Olemba Root, 1 Marshberry, 1 Telaari Frond and 1 Dragonspine.", progress = "Hello, dear.", completion = "You are very resourceful, {name}. Our greatest gatherers would have taken twice as long to collect the herbs.\n\n\n\nDo not be afraid.", sourceObjectiveStatus = "unverified-source-field" }
quests[10046] = { id = 10046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dark Portal", description = "Two weeks ago, our scouts reported a heavily armed Alliance force under the command of Field Commander Romus departing Nethergarde Keep. With so many soldiers and supplies, along with such a distinguished commander, they can only have one goal: Outland.\n\nThe warchief sent an advance force through the portal, but if the Alliance believes there is a need for that many troops, perhaps we'd be wise to send our own reinforcements.\n\nJourney through the Dark Portal and report to Nazgrel at Thrallmar.", sourceObjective = "Travel through the Dark Portal and speak with Nazgrel at Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10047] = { id = 10047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Glory", description = "The 'Path of Glory,' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people.\n\nIt wasn't enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light.\n\nThose tortured souls still wander these lands, crying out for release. I ask you, {name}, help me in this undertaking.", sourceObjective = "Cleanse 8 Trampled Skeletons on the Path of Glory with Draenei Holy Water, then return to Warp-Scryer Kryv at Honor Hold.", progress = "The cries seem somehow... fainter than they were before. The Light grant it's more than wishful thinking.", completion = "You have my sincere thanks for your efforts, {name}. Though much remains to be done, it gladdens me to know we have helped some find their long-deserved rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10048] = { id = 10048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Deirom.\n\nI won't need much, perhaps half a dozen handfuls, or so.", sourceObjective = "Collect 7 handfuls of Pacifying Dust for Andarl at the Allerian Stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10049] = { id = 10049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Dugar.\n\nI won't need much, perhaps half a dozen handfuls, or so.", sourceObjective = "Collect 7 handfuls of Pacifying Dust for Kurgatok at Stonebreaker Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10050] = { id = 10050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Souls", description = "Near the end of our invasion, the Armory to the south fell under attack by the Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and trapped their souls between the realms of the living and the dead.\n\nThose noble souls must be set free! I beg you, {name}, end my comrades' torment, for I have not the heart to slay them myself.", sourceObjective = "Honor Guard Wesilow wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south.", progress = "What I asked of you is a terrible thing to request of anyone. But what you must understand is many of the men won't go near the ruins. The memories and the pain are too fresh, but we can't allow the spirits to continue to wander.\n\nThe longer they persist, the more they shed their remaining ties to their past life and give themselves over to malevolence.", completion = "The Sons appreciate your efforts, even if few are willing to speak of the armory.", sourceObjectiveStatus = "unverified-source-field" }
quests[10051] = { id = 10051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of the Allerian Stronghold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!\n\nWe won't be able to do this on our own - you do have a group with you, right?", sourceObjective = "Escort Isla Starmane to safety and then report to Captain Auric Sunchaser at the Allerian Stronghold in Terokkar Forest.", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.  Nasty blood elves!\n\nShe told me how you were instrumental in saving her so that we could get that information.  Allerian Stronghold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10052] = { id = 10052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of Stonebreaker Hold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!\n\nWe won't be able to do this on our own - you do have a group with you, right?", sourceObjective = "Escort Isla Starmane to safety and then report to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.\n\nShe told me how you were instrumental in saving her so that we could get that information.  Stonebreaker Hold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10053] = { id = 10053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor to the southeast are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut beneath the fel orc settlement, and kill him. Once he is dead, search the cave for the fel orc battle plans. We must not be taken by surprise.", sourceObjective = "Defeat Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[10054] = { id = 10054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Honor Hold in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word to Lieutenant Amadi. You must stop the Bonechewer forces before they can launch their attack!", sourceObjective = "Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh, then make your report to Lieutenant Amadi at Honor Hold's western tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[10055] = { id = 10055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste Not, Want Not", description = "Reinforcements are great, but I don't see 'em haulin' any wagons loaded with ingots or timber.\n\nTake a look around, friend. Trees are in short supply, and the mines are overrun with Legion scum.\n\nI'm in a bad way fer supplies, and I'm makin' what substitutions I can, but it's time to start reusing what we can.\n\nThe southern edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of 'em are still usable. Feeling up to a bit o' a salvage operation?", sourceObjective = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Dumphry at Honor Hold.", progress = "Were you able to find any usable materials out there underneath all the dust, ash, and char?", completion = "This is in better condition than I thought it'd be. Sure, it's going to take some time to work off all the rust, the char, and the like, but I'll not complain.", sourceObjectiveStatus = "unverified-source-field" }
quests[10056] = { id = 10056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to the southeast serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nThe Sons of Lothar have been fighting them for some time, and the stories they tell would be nigh unbelievable if I hadn't seen these 'fel' orcs with my own eyes.\n\nSomething has changed them, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Go to Zeth'Gor and destroy any supplies you find there.", sourceObjective = "Destroy 6 piles of Bleeding Hollow Supplies and report to Lieutenant Amadi at Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10057] = { id = 10057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking to the Leadership", description = "The disturbances at Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nPerhaps we've been approaching this the wrong way. I've always assumed that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", sourceObjective = "Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Honor Guard Wesilow in the tower northwest of Honor Hold.", completion = "We can only hope that with the quieting of the ghosts of the officers, the spirits of the foot soldiers will follow. Thank you once again for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10058] = { id = 10058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Gift", description = "<The priest's gaze slowly moves from his mug to you.>\n\nDon't you know better than to bother a man in his cups?\n\nOh, what's the use? I suppose newcomers are a good sign. What would Turalyon think?\n\nI remember the eve of our departure, when I gave Mysteries of the Light to him. During the campaign and the ensuing years, he never forgot to read his daily passage to the men.\n\nWhen he left us again, he gave the book back to me. Like a fool, I believed it safe in my quarters to the south of the armory.", sourceObjective = "Retrieve Mysteries of the Light and return it to Father Malgor Devidicus at Honor Hold.", progress = "I thought I asked you not to bother me. What is it?", completion = "Is that really it? It's hard to believe it survived the battle. Conditions in the ruins haven't been kind to the book, but still, I'm glad to have it.\n\nIt's the only token I have of Turalyon.\n\n<Father Devidicus seems to be fighting back tears.>\n\nWhen you fight beside someone for so many years, they become closer than even family.", sourceObjectiveStatus = "unverified-source-field" }
quests[10059] = { id = 10059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing With Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut into the rock beneath the outpost, and kill him. Once he is dead, search the cave for the fel orc battle plans. Thrallmar must not be taken by surprise.", sourceObjective = "Slay Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[10060] = { id = 10060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Thrallmar in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word back to Thrallmar. You must stop the Bonechewer forces before they can launch their attack!", sourceObjective = "Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh. Then report to Stone Guard Ambelan at Spinebreaker Ridge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10061] = { id = 10061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unyielding", description = "When the Bonechewer fel orcs attacked the Expedition Armory, the garrison there fell quickly.  The battle was bloody and fierce, and there were no survivors.\n\nAlthough the dead were buried, their spirits continue to haunt those ruins.  Of late, I have been receiving visions that these spirits may soon become a threat to Thrallmar.\n\nThere is only one course of action to take.  We must grant these spirits rest.  You must overcome them in battle.", sourceObjective = "Grelag wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south of Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10062] = { id = 10062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking to the Leadership", description = "The disturbances at the Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nWe may be approaching this the wrong way. My visions suggested that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.You will be able to choose one of these rewards:", sourceObjective = "Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Grelag at Spinebreaker Ridge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10063] = { id = 10063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League, Is That Something for Gnomes?", description = "Babysitting! Would you believe it?\n\nThey pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome!\n\nI'd never heard o' a gnome wanting to become a prospector before, so I asked.\n\nSeems we are takin' gnomes now, and this particular one has a fascination with murlocs!\n\nWell, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!", sourceObjective = "Find Clopper Wizbang camped in an old turtle shell on the shore north of Blood Watch.", completion = "I thought so! That grumpy old dwarf was supposed to help me carry my equipment and gather data, but all he does is sit in that strange {race} town, drinking himself into a stupor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10064] = { id = 10064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to the Hand", description = "The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil.\n\nReport to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, {name}.", sourceObjective = "Report to Scout Jorli at Vindicator's Rest.", completion = "I was hoping Blood Watch would send reinforcements once they learned what we're up against.", sourceObjectiveStatus = "unverified-source-field" }
quests[10065] = { id = 10065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting a Path", description = "During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch.\n\nThe problem is that we'd have to abandon our position here in order to guarantee a safe return.\n\nAs soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers, it might allow us to make the trip back safely.", sourceObjective = "Kill 10 Enraged Ravagers and return to Scout Jorli at Vindicator's Rest.", completion = "It looks a bit better out there, but I still wonder if I wouldn't be better off waiting for a medic here.", sourceObjectiveStatus = "unverified-source-field" }
quests[10066] = { id = 10066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, the Tangled Webs They Weave", description = "We don't dare abandon our post, or wander too far from Vindicator's Rest, {race}. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals.\n\nThe mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior.\n\nWe'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, {name}.", sourceObjective = "Kill 8 Mutated Tanglers and report to Vindicator Corin at Vindicator's Rest.", progress = "Have you managed to clear any of the mutated tanglers?", completion = "Well done, {name}. It's going to be much easier to get reinforcements from Blood Watch, or launch strikes against the Sunhawks without having to worry about what the tanglers are up to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10067] = { id = 10067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fouled Water Spirits", description = "Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal.\n\nI've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.", sourceObjective = "Kill 6 Fouled Water Spirits and return to Vindicator Corin at Vindicator's Rest.", progress = "Have you begun to clear the fouled water spirits?", completion = "Well done, {name}. It's important not to overlook any opportunity to deny the Sunhawks sustenance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10068] = { id = 10068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well Watcher Solanian", description = "And now, I need for you to do something.\n\nWell Watcher Solanian is in need of your services.  You would do well to ingratiate yourself with him.\n\nHe awaits you on the exterior platform that the ramp in this chamber leads up to.", sourceObjective = "Speak with Well Watcher Solanian at the Sunspire on Sunstrider Isle.", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10069] = { id = 10069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well Watcher Solanian", description = "And now, I need for you to do something.\n\nWell Watcher Solanian is in need of your services.  You would do well to ingratiate yourself with him.\n\nHe awaits you on the exterior platform that the ramp in this chamber leads up to.", sourceObjective = "Speak with Well Watcher Solanian at the Sunspire on Sunstrider Isle.", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
