quests[10073] = { id = 10073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well Watcher Solanian", description = "And now, I need for you to do something.\n\nWell Watcher Solanian is in need of your services.  You would do well to ingratiate yourself with him.\n\nHe awaits you on the exterior platform that the ramp in this chamber leads up to.", sourceObjective = "Speak with Well Watcher Solanian at the Sunspire on Sunstrider Isle.", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10074] = { id = 10074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", sourceObjective = "Chief Researcher Amereldine at Halaa wants 20 Oshu'gun Crystal Powder Samples.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, {name}. This will help us in our battle against the Alliance filth that have surfaced in the Outland.", sourceObjectiveStatus = "unverified-source-field" }
quests[10075] = { id = 10075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "I am always accepting crystal powder contributions, {name}. You will be compensated for each set of samples that you recover." }
quests[10076] = { id = 10076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", sourceObjective = "Chief Researcher Kartos at Halaa wants 20 Oshu'gun Crystal Powder Samples.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, {name}. This will help us in our battle against the Horde filth that have surfaced in the Outland.", sourceObjectiveStatus = "unverified-source-field" }
quests[10077] = { id = 10077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "I thank you for your contribution, {name}. Should you find more, you know where to bring them!" }
quests[10078] = { id = 10078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Waste to the Unwanted", description = "Now that we've gotten our salvage operation off the ground, it's time to begin the second phase of the plan.\n\nAcross the Path of Glory, the Horde still has their old blade throwers trained on us. Don't let their age fool you, {name}, they're still very dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is going to dismantle their weaponry.\n\nTake this torch and burn the remaining siege equipment. I'll take no chances with Honor Hold's safety.", sourceObjective = "Use the Flaming Torch to burn the Horde Blade Throwers overlooking the Path of Glory. Then, bring the Flaming Torch to Dumphry in Honor Hold.", progress = "You seem to be in good spirits. Has burning Horde siege machinery put the spring back in your step?", completion = "That's the spirit!\n\nI'm glad we finally got some reinforcements, but I'm not so sure about their attitude toward the Horde. Where I come from, anyone with a weapon pointed at you is an enemy and needs to be dealt with like one!", sourceObjectiveStatus = "unverified-source-field" }
quests[10079] = { id = 10079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits!\n\nNot only did they run all my workers out of the tunnels, but they're pounding away in there night and day! To make things worse, now I've got Danath on me back! He says he's going to take away me ale ration if I don't get this taken care of soon!\n\nNone of the miners'll go in there, and the guards are busy drinking themselves silly.\n\nI'm begging you, {name}, help me here. Danath can take me dignity, but he'll never take me ale!", sourceObjective = "Kill 12 Gan'arg Sappers and return to Foreman Biggums.", progress = "Tell me the shaking's over and my boys can get back to work... please?", completion = "By Bronzebeard's bronze... beard, you've done it! You're a hero, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10080] = { id = 10080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camps of the Legion", description = "If you've spoken to Humphry, he's undoubtedly told you that he finds the infestation in the mines a minor annoyance, but I know it for what it is: a symptom of a larger evil.\n\nTo the northeast of the Horde outpost of Thrallmar, the Legion's minions labor night and day on something, but what is it?\n\nNone of the scouts I've dispatched to the camps have ever returned. The time for subtlety has passed, {name}. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.", sourceObjective = "Kill 10 Gan'arg Servants, 5 Forge Camp Legionnaires, and 5 Sisters of Grief, then search Forge Camp: Rage for evidence of the Legion's intentions.", sourceObjectiveStatus = "unverified-source-field" }
quests[10081] = { id = 10081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Meet Mother Kashur", description = "Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur.\n\nYou will find her a great ways to the southwest, at the Ancestral Grounds.", sourceObjective = "Greatmother Geyah wants you to speak with Mother Kashur.", completion = "The potion that you drank has no real effect. You can only see a spirit if they allow it. The potion is merely a symbol of your belief and dedication. It was a test and you passed...", sourceObjectiveStatus = "unverified-source-field" }
quests[10082] = { id = 10082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Agitated Ancestors", description = "Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed.\n\nAs of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest.\n\nThese ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits. Do this and return to me.", sourceObjective = "Mother Kashur has asked that you put to rest 15 Agitated Orc Spirits.", progress = "You do not need a potion to see spirits, {name}.", completion = "It's no use. They continue to rise. There must be something more insidious underway.", sourceObjectiveStatus = "unverified-source-field" }
quests[10083] = { id = 10083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion's Plans", description = "You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.\n\nField Marshall Rohamus mentioned another camp to the west, Forge Camp: Spite. Could that be where the Legion is keeping the other half of the plans?\n\nIf the Legion has undertaken a massive production campaign, assembling at multiple sites would make sense.", sourceObjective = "Retrieve the Forge Camp: Spite Plans and return them to Field Marshal Rohamus at Expedition Point.", sourceObjectiveStatus = "unverified-source-field" }
quests[10084] = { id = 10084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Mageddon", description = "With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll begin churning out fel reavers before we can get word to Nethergarde.\n\nWe have no choice but to move against them as soon as possible. We cannot strip Honor Hold's defenses to support you in this offensive, for to do so would be suicide. The fel orcs and the Horde will pounce on us at the first sign of weakness.\n\nHonor Hold has stood for 20 years, and we don't intend to lose it now.You will be able to choose one of these rewards:", sourceObjective = "Kill Nightlord Malphas at Forge Base: Mageddon, and report to Force Commander Danath Trollbane at Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10085] = { id = 10085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit With The Ancestors", description = "I need for you to journey to the villages of the ancestors, {name}. Seek each one out and see if the ancestors remain.\n\nVisit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east.\n\nReturn to me once you have observed the ancestors in their homes.", sourceObjective = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you Visit Sunspring Post, Visit Laughing Skull Ruins, Visit Garadar and Visit Bleeding Hollow Ruins.", progress = "Move as the wind, {name}.", completion = "This is very troubling. You say that none of the ancestors were at their villages? That they were all moving south?", sourceObjectiveStatus = "unverified-source-field" }
quests[10086] = { id = 10086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Work... For the Horde!", description = "Would you believe it?  These orcs hired me to help them shore up damaged fortifications and build explosives.  What a dream job!  It's too bad we're so short on materials, but a clever goblin like myself learns how to make do!\n\nCan you help me?  I need salvaged wood and metal from the ruined battlements along the Path of Glory.  Go down there and salvage, and watch out for those red-skinned orcs!\n\nWhen you're done, come back for big rewards!", sourceObjective = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Megzeg Nukklebust in Thrallmar.", progress = "So how did the salvage mission go?  Did you find anything useful?", completion = "This stuff is great!  A little bent and a little burnt, but I've never let low grade materials stop me from making precision high explosives.\n\nThanks, {name}.  You really have an eye for quality trash!", sourceObjectiveStatus = "unverified-source-field" }
quests[10087] = { id = 10087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn It Up... For the Horde!", description = "I'm a lucky, lucky goblin.  I get to make explosives and killing machines, knowing they'll be used immediately on important missions!\n\nSpeaking of missions, I just got one from Thrallmar command: burn the Alliance cannons on the far side of the Path of Glory... the ones pointing dangerously close to Horde fortifications.  Take this torch and make your way to each cannon.  Fire the torch and watch the sparks fly!", sourceObjective = "Use the Flaming Torch to burn the Eastern Alliance Cannon and the Western Alliance Cannon, and then return to Megzeg Nukklebust in Thrallmar.", progress = "I've been looking for the telltale signs of burning cannons -- smoke plumes, or the cries of burning fel orcs...\n\nAny luck on your mission?", completion = "I thought so!  I couldn't quite make out the destruction from here, but I can imagine how it must have looked.  Splendid!\n\nWell done, {name}.  Thrallmar command will be happy to hear of your success!", sourceObjectiveStatus = "unverified-source-field" }
quests[10088] = { id = 10088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disturbances coming from the mine, but that's the least of my problems.\n\nIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?", sourceObjective = "Kill 12 Gan'arg Sappers and return to Foreman Razelcraz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10089] = { id = 10089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camps of the Legion", description = "Thrallmar has been subjected to bombardment from the Legion Camps since its establishment. We've managed to hold out so far, but the situation is getting more desperate with every day.\n\nShadow Hunter Ty'jin has made several attempts to learn more about the camps, but none of his scouts ever returned.\n\nThe time for subtlety has passed, {name}. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.", sourceObjective = "Kill 10 Gan'arg Servants, 5 Forge Camp Legionnaires, and 5 Sisters of Grief, then search Forge Camp: Rage for evidence of the Legion's intentions.", sourceObjectiveStatus = "unverified-source-field" }
quests[10090] = { id = 10090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion's Plans", description = "You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.\n\nThe glyphs indicate that another camp to the west, Forge Camp: Spite, is also involved in the project. Could that be where the Legion is keeping the other half of the plans?\n\nIf the Legion was forging something truly monstrous, assembling it at multiple sites would make sense.", sourceObjective = "Retrieve the Forge Camp: Spite Plans and return them to Overlord Hun Maimfist at Reaver's Fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10091] = { id = 10091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Devices", description = "Gah!  They've been torturing me, trying to get me to tell them everything that I know.\n\nI failed - they fed the others to Hellmaw, and I was to be next.  But I told them nothing!\n\nThey're crazy!  They're hell-bent on summoning demonic forces that they have no way of controlling!\n\nThey're using special devices to make their soul shards, and their summoning, more powerful.  You must steal these devices!\n\nI would join you, but I must return to Shattrath City to report to the Lower City's spymistress.", sourceObjective = "Steal 5 Soul Devices and deliver them to Spymistress Mehlisah Highcrown at the Terrace of the Light in Shattrath City.", progress = "Yes?  What can I do for you, {class}?", completion = "To'gun was here earlier giving me his report.  He should have stayed with you to help!\n\nI sent him back out there to assist Grik'tha.  I think they make a cute couple.\n\nSo, these are the soul devices that the Shadow Council were using to enhance their summoning power?  They look dangerous to me - maybe the Scryers will know what to do with them?\n\nPlease, take one of these as a reward for crippling the Shadow Council's operation in the labyrinth.", sourceObjectiveStatus = "unverified-source-field" }
quests[10092] = { id = 10092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Mageddon", description = "With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll have churned out a fleet of fel reavers before we can get word to Orgrimmar.\n\nWe have no choice but to move against them as soon as possible. I cannot use Thrallmar's garrison to support you, since it would leave us too vulnerable.\n\nThere are any number of opportunists, the Alliance notwithstanding, who would eagerly pounce on our unprotected outpost. Do not fail, {name}. Too much depends on you.You will be able to choose one of these rewards:", sourceObjective = "Kill Nightlord Malphas at Forge Base: Mageddon, and return to Overlord Hun Maimfist at Reaver's Fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10093] = { id = 10093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Telhamat", description = "Fortunately, the Path of Glory is not the only trace of my people in these lands. To the west, a few of our holy sites survive, although some have been overrun.\n\nWhile Velen prepared for the journey that would lead him to Azeroth, those of us who would remain behind sought to reestablish a presence at our holy places.\n\nIn the western part of the Hellfire Peninsula, you will find a small group of draenei at the Temple of Telhamat, led by Amaan the Wise. I am certain he'd be interested in meeting you.", sourceObjective = "Speak with Amaan the Wise at the Temple of Telhamat in western Hellfire Peninsula.", completion = "Ah, so you've met Seer Kryv. He is a wise and gifted man and any {race} he would name a friend is also a friend of mine.\n\nMake yourself comfortable and introduce yourself to the others who call the temple home.", sourceObjectiveStatus = "unverified-source-field" }
quests[10094] = { id = 10094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Blood", description = "It has been two years since the Shadow Council summoning that resulted in the explosion of this once-great mausoleum, and the formation of the Bone Wastes.\n\nNow they are at war with an unbelievably powerful force on the inside.\n\n{name}, you must make your way into the Shadow Labyrinth to determine what they are up against, and to see if it poses a threat to us.  Our spies speak of their use of a forbidden book of unholy summoning, known only as the Codex of Blood.\n\nSeek your answers within its pages.", sourceObjective = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!\n\nYou read on, but what you read seems unbelievable!", sourceObjectiveStatus = "unverified-source-field" }
quests[10095] = { id = 10095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago!  It is what caused the explosion of Auchindoun, and the creation of the Bone Wastes beyond.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!\n\nWith the grandmaster, and the rest of their leadership dead, you are Outland's last hope against this monstrosity!\n\n{name}, you know at the core of your being that you and your companions dare not fail!", sourceObjective = "Destroy Murmur and inform Spymistress Mehlisah Highcrown at the Terrace of Light in Shattrath City of the events that have transpired inside the Shadow Labyrinth.", completion = "Murmur almost broke free?!  They've had that thing contained in there for two years... I wonder what they did wrong to lose control over it after all this time?\n\n{name}, by putting that beast down you've likely saved all of us!  I cringe to think what would have happened to all of us here, and the rest of Outland, if that thing had somehow managed to break free!\n\nI'm glad you helped us to take matters into our own hands and deal with the Shadow Council threat at Auchindoun.  How can we ever reward you?", sourceObjectiveStatus = "unverified-source-field" }
quests[10096] = { id = 10096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Sporeloks", description = "Ikeyen's been telling me stories about what happened to him down in those caves and I think it's just awful!\n\nYou know, maybe we should do something to help out those poor sporeloks.  Ikeyen says that they live there in the Funggor Cavern, but that the marsh beasts have recently invaded.\n\nWhy don't you go down there and see if you can clear some of those marsh beasts out?  It's just to the southwest.", sourceObjective = "Slay 10 Marsh Dredgers and 10 Marsh Lurkers, and then return to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", progress = "What?  Back so soon?  How did it go?", completion = "Good!  Those marsh beasts have no right to invade the home of the sporeloks!\n\nIt would be better if these creatures would learn to live in harmony, but when that's not possible, we'll be here to take care of the situation!\n\nHere, please take one of these as thanks for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10097] = { id = 10097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "The Sethekk departed Skettis with great fanfare when Auchindoun exploded. Surely it must've been an omen of our master's arrival.\n\nMy brother, Syth, was one of their leaders and told us we were obligated to go into the temple ruins and face our god.\n\nAfter we took up residence in the ruins, calling them the Sethekk Halls, I began to doubt my brother and his ally, Ikiss.\n\nIn time, Syth had me cast out of the Halls, but he refused to let me take our sister Lakka with me. Will you help me rescue her?", sourceObjective = "Kill Darkweaver Syth in the Sethekk halls, then free Lakka from captivity. Return to Isfar outside the Sethekk Halls when you've completed the rescue.", progress = "Did you find her, {name}? Was she still being held within the halls?", completion = "I can't thank you enough, {name}. Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him. Perhaps his spirit will find rest once it has atoned for leading our people astray.", sourceObjectiveStatus = "unverified-source-field" }
quests[10098] = { id = 10098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Legacy", description = "My people honor an ancient hero named Terokk. Arakkoa hatchlings are regaled with stories of his deeds and descriptions of his beautiful plumage.\n\nHe dwelt among my people for hundreds of years, but mysteriously vanished one day, leaving only his mask, spear, and writings behind.\n\nThe relics are cherished by the arakkoa, but they were heartbroken when the Sethekk bore the objects away from Skettis at their departure.\n\nI have written down what little I know about their location within the halls.", sourceObjective = "Bring Terokk's Mask, Terokk's Quill, and the Saga of Terokk to Isfar outside the Sethekk Halls.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself.\n\nThank you for helping me in this, {name}. You have no idea of the magnitude of what you've done this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[10099] = { id = 10099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mastermind", description = "Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place!\n\nThere's got to be someone down there in the deepest reaches of the mine directing the incursion. You seemed to do well against them last time, and Light knows you're the only one brave enough to venture back into the mine. Find out who's responsible for this disturbance and make him pay!", sourceObjective = "Locate and kill Z'kral in the mines beneath Honor Hold, then report back to Foreman Biggums.", progress = "I'm almost afraid to ask. Seeing you come out of the mine alive means one of two things: either you killed the bastard, or you lost your nerve. Well, which is it?", completion = "I'm glad you managed to take care of, of... what did you say he called himself? Z'kral?\n\nFrom your description, it sounds more like an 'it' than a 'him' but all that matters is it's dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[10100] = { id = 10100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mastermind", description = "Don't get me wrong, {name}, I'm glad that you agreed to help with the mines, but for every sapper you killed, I swear two more appeared.\n\nI've been giving Watch Commander Krunk an earful, but he's still refusing to send me any help. He keeps muttering something under his breath about helboars. If I wasn't so sure he'd hit me, I'd tell him this is no time to be thinking about ribs!\n\nAnyway, it looks like there's someone down there deep in the mines directing this whole thing. Find him and kill him!You will be able to choose one of these rewards:", sourceObjective = "Locate and kill Urga'zz within the mines beneath Thrallmar, then return to Foreman Razelcraz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10101] = { id = 10101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Spirits Speak", description = "Oshu'gun - the diamond mountain - was once sacred to my people. It was there that the clans would gather every year to celebrate the springtime festival. It was there that our shaman communed with the honored ancestors. It was the center of our culture - until the shadows overtook us. When the clans became a horde, the spirits of Oshu'gun fell silent. The ancestors turned their backs on us.\n\nYet something now draws them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.", sourceObjective = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you seek out the vision you had. Find K'ure in Oshu'gun.", completion = "<A gentle, melodic voice fills your mind.>\n\nI am K'ure of the naaru, {name}. You stand within the heart of my ancient vessel. \n\nOshu'gun, as the orcs named it, is the ship that first brought the draenei to this world.  Though we fell from the heavens and crashed here many hundreds of years ago, my weakened energies have remained trapped within this wreckage. Regrettably, I am the source of the orc spirits' pain.", sourceObjectiveStatus = "unverified-source-field" }
quests[10102] = { id = 10102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Secret Revealed", description = "As my energies bled away over the centuries, a void slowly grew in my place - devouring the souls of those nearby. Helplessly, I watched as generations of orc souls were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to draw countless void minions into their Burning Legion.\n\nNow, the key to ending this cycle and freeing the orc spirits lies with another naaru - A'dal. I have sensed his essence within the ancient city of Shattrath in the Terokkar Forest.", sourceObjective = "Speak with A'dal in Shattrath City.", completion = "K'ure was wise to send you here. While we cannot assist you with the suffering of the orc ancestors, there is one that can.\n\nOne that is soon to be reborn of Light...", sourceObjectiveStatus = "unverified-source-field" }
quests[10103] = { id = 10103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Zurai", description = "With the arrival of Field Commander Romus and his forces, the Alliance and their draenei friends have grown bold. They're militarizing every old draenei ruin from here to Shattrath.\n\nIn response, the trolls have established a new outpost in the eastern part of Zangarmarsh, just south of the Dead Mire. Swamprat Post, they're calling it. I'm glad they have a sense of humor about living in a place like that, because I wouldn't relish it.\n\nThe post's commander has asked me to send anyone I can spare.", sourceObjective = "Report to Zurai at Swamprat Post in Zangarmarsh.", completion = "To be honest, I had expected more, but you'll have to do. Welcome to Swamprat Post.", sourceObjectiveStatus = "unverified-source-field" }
quests[10104] = { id = 10104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerns About Tuurem", description = "The rumors from Tuurem are unsettling. Some say the town's ruins are overrun with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei relics.\n\nIt's hard to know which are true and which aren't, but we have a responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian Stronghold in Terokkar Forest. He is something of a student of magical relics. More than anyone else, he's likely to know what's going on there.", sourceObjective = "Speak with Andarl at the Allerian Stronghold in Terokkar Forest.", completion = "I'm flattered that your Broken friend considers me a scholar of his people's relics, but to be honest, I haven't had much chance to study them since my arrival here. It was certainly my intent, but when I arrived, I found that there were other matters that required my attention.", sourceObjectiveStatus = "unverified-source-field" }
quests[10105] = { id = 10105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News for Rakoria", description = "Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress.\n\nShe's sharp and capable, {name}, but be careful around her. She's got a lot of a goods she's eager to move along the roads, but don't assume she's got our best interests at heart. Rakoria goes where she believes there's profit to be found.", sourceObjective = "Speak with Rakoria at Stonebreaker Hold in Terokkar Forest.", completion = "I'd hoped his men would have the outpost complete sooner, but it's not costing him money. Still, it's progress.", sourceObjectiveStatus = "unverified-source-field" }
quests[10106] = { id = 10106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", progress = "{name}, return to me when you have aided in the capture of each of the forts!", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[10107] = { id = 10107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Measures", description = "Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, {name}!\n\nBe warned, he is a blademaster...", sourceObjective = "Jorin Deadeye at Garadar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?", sourceObjectiveStatus = "unverified-source-field" }
quests[10108] = { id = 10108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Measures", description = "The huntress's agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, {name}!\n\nBe warned, he is a blademaster...", sourceObjective = "Mo'mor the Breaker at Telaar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?", sourceObjectiveStatus = "unverified-source-field" }
quests[10109] = { id = 10109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Must Have Them!", description = "Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! Say, you look like you might be of some use.\n\nI'll tell you what, {race}; if you gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can't you do is more like it...\n\nI'll need air elemental gas from the air elementals of Nagrand. They're all over the place so don't ask me where to find 'em!", sourceObjective = "Wazat across from Clan Watch in southern Nagrand wants you to bring him 3 Air Elemental Gases.", progress = "Got gas?", completion = "Excellent! Now just a few adjustments and this thing will be as good as new. Oh yes, your key! Here you go.\n\nBy the way, the Jump-a-tron still has a few kinks that I need to work out. Um, just be careful.", sourceObjectiveStatus = "unverified-source-field" }
quests[10110] = { id = 10110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", progress = "Return to me after you have helped capture each fort!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[10111] = { id = 10111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me The Egg!", description = "Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump.", sourceObjective = "Wazat in Nagrand wants you to use the Jump-a-tron 4000 to get to the nest in the nearby tree and steal the Mysterious Egg.", progress = "Did I mention my love for eggs?", completion = "Well, it's no egg... Hey! I love chicken too! I'll just chomp right through this ginourmous talon! Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[10112] = { id = 10112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Favor", description = "Hmmm?  A box you say?  Or was it several?  Do you know what material the box was constructed from?\n\nAnd what was the name of this merchant?  Empoor?  Are you certain that he's one of the Broken?  I don't do much business with their kind.\n\nPerhaps my memory would be jogged if you were to do me a favor?\n\nThe Skithian arakkoa - primitive casters that they are - recently stole a huge shipment of my more exotic goods.  I want it all back!\n\nYou can find Veil Skith just to the south of Shattrath City.", sourceObjective = "Retrieve 5 of Lathrai's Stolen Goods. Return them to Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City.", progress = "Hmm, is my memory improving?", completion = "Yes, indeed, I do believe that it's all getting clearer now.\n\nAnd I think that your diligence in this matter deserves more than just the information that you seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[10113] = { id = 10113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nesingwary Safari", description = "\"Go out and find us some supplies,\" he said. I was nearly killed about 15 times before I found this place! These Broken might not be the most hospitable bunch but at least they're not trying to tear my skin from my bones.\n\nAnyway, I'm not going back. My days of huntin' big game are over. If you end up heading northeast towards Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" quit. \n\nHey, maybe you can take my place! Good luck, stranger.", sourceObjective = "\"Shotgun\" Jones wants you to speak with Hemet Nesingwary at the Nesingwary Safari on the outskirts of northeast Nagrand.", completion = "I suppose we'll have to find a replacement water boy. Say, you look like a powerful {class}. Interested in a job? Or did you come for the hunt?", sourceObjectiveStatus = "unverified-source-field" }
quests[10114] = { id = 10114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nesingwary Safari", description = "These orcs have never seen a tauren before - if you can believe such a thing. If it weren't for Captain Kroghan, they would have probably been serving me for their next meal right about now.\n\nBut where are my manners? I am Ohlorn Farstrider, hunter extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in search of big game. If you are interested in the hunt, perhaps you should visit my crew at the Nesingwary Safari, due east of here near the border of Zangarmarsh.", sourceObjective = "Ohlorn Farstrider wants you to speak with Shado 'Fitz' Farstrider at the Nesingwary Safari in Nagrand.", completion = "I am relieved to hear that he is safe. Have you come to join the hunt?", sourceObjectiveStatus = "unverified-source-field" }
quests[10115] = { id = 10115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggerfen Deviance", description = "The Kurenai and the draenei don't always see eye to eye, particularly on the issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we won't pursue them. Some draenei are intent on 'redeeming' them all.\n\nHowever, there are times when even the Lost Ones go too far, such as the Daggerfen. In their village to the west, they dabble in poisons and deceit, arts that come unnaturally to us.\n\nWe must put an end to this before the vile Daggerfen can extend their influence.", sourceObjective = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers.", progress = "Have you seen what the Daggerfen have done? Now you understand why we must isolate them from the other Lost Ones.", completion = "You have done well, {name}. The Daggerfen are beyond redemption by anyone's standards, but I'm not certain that the draenei would've acted with the proper speed in this situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10116] = { id = 10116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against the Orebor Harborage.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous Kurenai and draenei and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the west of the Orebor Harborage.\n\nTo claim the bounty, present proof of the chietain's demise to Ikuti.", sourceObjective = "Bring Chieftain Mummaki's Totem to Ikuti at the Orebor Harborage.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "Remarkable! There have been others who tried to claim the bounty, but they never returned. It's not hard to figure out what happened to them.\n\nI'm relieved that we'll no longer be troubled by Mummaki and his degenerates.", sourceObjectiveStatus = "unverified-source-field" }
quests[10117] = { id = 10117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous scouts and messengers and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the northwest of Zabra'jin.\n\nTo claim the bounty, present proof of the chietain's demise to Shadow Hunter Denjai.", sourceObjective = "Bring Chieftain Mummaki's Totem to Shadow Hunter Denjai.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "You have my thanks, {name}. I was beginning to think that I was going to have to take a substantial part of the garrison up there and deal with Mummaki myself. Of course, there's no telling what might have happened to Zabra'jin then.", sourceObjectiveStatus = "unverified-source-field" }
quests[10118] = { id = 10118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to the Daggerfen", description = "Of all the Lost One tribes in Zangarmarsh, the Daggerfen are the most cunning and most aggressive. They are highly organized and make no secret of the fact that they desire control over the other Lost Ones in the marsh.\n\nTheir attacks have already taken quite a toll on my scouts and messengers. I cannot afford to lose any more men.\n\nIf we don't act soon, they'll have complete control over the roads and Zabra'jin will effectively be surrounded.", sourceObjective = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers and return to Shadow Hunter Denjai at Zabra'jin.", completion = "I think you've managed to send a fairly strong message to them. Perhaps now, the rest of my men won't be so afraid to take the fight to the Daggerfen. Or, if they are, they'll find themselves ashamed by their lack of bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[10119] = { id = 10119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dark Portal", description = "For 20 years the Dark Portal has remained a silent monument - a eulogy to a time long since forgotten.\n\n<Relthorn looks around.>\n\nI never thought to see this day, yet here we stand, looking into the abyss.\n\nOn the other side of this gate we are locked in a savage war - a war that we cannot win without support. You must go through the Dark Portal and help our troops, {class}.\n\nReport to Commander Duron at once. He awaits you in Outland...", sourceObjective = "Travel through the Dark Portal and find Commander Duron. He awaits your arrival on the other side - in the Outland.", completion = "Welcome to Outland, {name} -- welcome to the nightmare! Though the initial Expeditionary Force made it through unscathed, the Legion is attempting to retake the Dark Portal and prevent any of our reinforcements from coming through.\n\nAs much as I'd like your aid here, our troops and the Horde soldiers are able to fend off the Legion platoons that are attempting to take control of this platform.\n\nWe need you where your talents can best be utilized.", sourceObjectiveStatus = "unverified-source-field" }
quests[10120] = { id = 10120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrival in Outland", description = "Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather who stands on the platform behind us. She'll speed you on your way.", sourceObjective = "Lieutenant General Orion at the Dark Portal in Hellfire Peninsula wants you to bring Orion's Report to Vlagga Freyfeather.", progress = "I saw you speaking with Orion - it must be important business...", completion = "So you're Orion's new messenger? I pray you fare better than the last one he sent, {class}.  With the Legion pressing in, you'd never make it to Thrallmar on foot. Say the word, and my faithful wyvern will deliver you there safely.", sourceObjectiveStatus = "unverified-source-field" }
quests[10121] = { id = 10121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eradicate the Burning Legion", description = "Though this land is full of strange new enemies, the Burning Legion is still the greatest threat to our Expedition. One of my most trusted warriors, Sergeant Shatterskull, has been studying the Legion's tactics - trying to discern the demons' true purpose in this land. Seek him out at the supply caravan just outside the southern wall.\n\nAnd {name} - be wary of the Legion. Their evil cannot be underestimated.", sourceObjective = "Speak with Sergeant Shatterskull at the Supply Caravan just outside of Thrallmar, to the east.", completion = "No doubt you saw the Legion's warriors dotting the landscape on your flight from the Dark Portal. Though we defeated them at the Battle of Mount Hyjal some five years past, the cursed demons just keep coming back for more. If it's a challenge they crave, then the Horde will answer in kind!\n\nWe orcs have more than just a score to settle with the Legion. What about you, {name}? Shall I tell you of our enemy?", sourceObjectiveStatus = "unverified-source-field" }
quests[10122] = { id = 10122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable scouts, Private Imarion, to track their movements, preparations and numbers, but he hasn't returned to report his findings.\n\nImarion was to focus his efforts on the northernmost camp along the Southern Rampart, near where it joined the Citadel. Find him, {name}. Without his information, we're sitting ducks.", sourceObjective = "Search the northernmost camp along the Southern Rampart for any trace of Private Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10123] = { id = 10123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felspark Ravine", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", sourceObjective = "Sergeant Shatterskull at the Supply Caravan east of Thrallmar in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", progress = "Thrallmar is safe so long as the arcanist and his bloodmages remain at the front.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth more dreadlords.\n\nNow for the bad news: I've got your new orders...", sourceObjectiveStatus = "unverified-source-field" }
quests[10124] = { id = 10124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Base: Reaver's Fall", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Foward Commander To'arch.\n\nNow move out!", sourceObjective = "Report to Forward Commander To'arch at Reaver's Fall.", completion = "So you're the one responsible for clearing out Felspark, eh?  That's good to hear - we need soldiers like you who can take these fiends head on!", sourceObjectiveStatus = "unverified-source-field" }
quests[10125] = { id = 10125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Disrupt Communications", description = "Directly east of here is the Legion Front. The front acts as a mobile command station for the Burning Legion. Jutting out of the ground you'll see Legion antennas. The Legion uses these to communicate with their forge camps throughout Outland. They also serve as wards to scramble Legion transmissions, making magical surveillance impossible.\n\nI want you to take these explosives and use them to obliterate the antennas. Get all of them, {name}. They run south to north on the border of the Legion Front.", sourceObjective = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you use To'arch's Explosives and destroy Legion Antenna: Spite, Legion Antenna: Rage, Legion Antenna: Hate, Legion Antenna: Fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[10126] = { id = 10126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their human prisoner south for interrogation.\n\nLieutenant Amadi mentioned that the Southern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Private Imarion.\n\nJudging by the note's mention of interrogation, it seems the private's fel orc captors see some value in keeping him alive. Pick up the trail before they decide to change their minds.", sourceObjective = "Travel south along the west side of the South Rampart and search the next camp for signs of Private Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10127] = { id = 10127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Sever the Tie", description = "It would be a dereliction of duty if I did not order you to take out the demons that inhabit the Legion Front, just east of this base.\n\nBoth sides of the front are set up in the same manner: Fel handlers roam between Legion encampments, which are in turn guarded by wrathguards. A shivan subjugator oversees the entire operation. Kill 'em all and let Kazzak sort 'em out.\n\nAnd watch out for patrolling fel reavers. I know you're tough but those things will make short work of you.", sourceObjective = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula wants you to kill 4 Fel Handlers, 8 Wrathguards, and Subjugator Shi'aziv.", sourceObjectiveStatus = "unverified-source-field" }
quests[10128] = { id = 10128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Private Imarion", description = "The tracks lead south from Imarion's equipment, appearing to follow the Southern Rampart. The roughness of the shallow ruts suggests that Imarion's captors were in a hurry to move him to his next destination, but why?\n\nWas someone waiting there for him, perhaps the Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Private Imarion, you're likely to find Warboss Nekrogg too.", sourceObjective = "Continue south along the Southern Rampart and search for where Warboss Nekrogg is holding Private Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10129] = { id = 10129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Gateways Murketh and Shaadraz", description = "We've identified the two main transporters that the Burning Legion are using to bring in reinforcements: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into oblivion!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Brack -- he'll put you on a wyvern.", sourceObjective = "Speak with Wing Commander Brack, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander To'arch at Reaver's Fall.", progress = "If you missed during your first pass, take another...", completion = "That will set them back weeks! Fantastic work, {name}. The Legion never expected such heavy resistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10130] = { id = 10130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Honor Hold.\n\nWith the hold's garrison concentrating on its eastern walls, an attack from the west would be devastating. Honor Hold can only hope to hold out if the western forces are kept out of the battle.", sourceObjective = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Lieutenant Amadi at Honor Hold's western guard tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[10131] = { id = 10131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planning the Escape", description = "Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.\n\nHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that orc he's managed to capture.\n\nIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.", sourceObjective = "Kill a Shattered Hand Grenadier and bring his Crude Explosives to Private Imarion at Gor'gaz Outpost.", sourceObjectiveStatus = "unverified-source-field" }
quests[10132] = { id = 10132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colossal Menace", description = "You see that huge red crystal to the north?  It fell from the sky not long ago, causing a massive earthquake.\n\nWhen we came out here to investigate the disturbance, we found all of these colossi wandering about that weren't previously here.\n\nThere's definitely something strange about that crystal and the energies that it's emanating, but I don't have time for that.  Those mountain giants are my immediate concern.\n\nI want you to head up to Fallen Sky Ridge with some friends and deal with them.", sourceObjective = "Slay 5 Raging Colossi and then return to Tola'thion at the Cenarion Post in Hellfire Peninsula.", completion = "Good work.\n\nIf you ask me, all that we have to do is kill enough of those colossi, and then we won't have to worry any longer about the ridge or that strange crystal in the middle of it.\n\nHere, take one of these as a gift from the Cenarion Expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[10133] = { id = 10133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Kill the Messenger", description = "Your handiwork is already causing the Legion great discomfort, {name}. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!\n\nWhat I ask of you next is more than I would ask of an ordinary soldier.\n\nThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.", sourceObjective = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive.", sourceObjectiveStatus = "unverified-source-field" }
quests[10134] = { id = 10134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crimson Crystal Clue", description = "As the colossus falls under the weight of your attacks, you notice for the first time that it was holding a red crystal fragment.\n\nWhile it was small and unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry around.  It also suspiciously looks like it's a piece of the giant crystal in the middle of the ridge.\n\nIt's most definitely a clue as to the strangeness that is occurring here, and you're sure that the druids at the Cenarion Post to the south will want to see it.", sourceObjective = "Deliver the Crimson Crystal Shard to Tola'thion at the Cenarion Post in Hellfire Peninsula.", progress = "That's a big crystal you have there.  Did you get that while you were up at the ridge killing colossi?\n\nLet me take a look at it.", completion = "Hmph.  Just looks like a big lump of unrefined crystal to me.\n\nAdmittedly, I can feel a sickly, evil aura emanating off of it, but that's not exactly in my line of work.  I'm just here to put an end to the mountain giant menace.", sourceObjectiveStatus = "unverified-source-field" }
quests[10135] = { id = 10135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Be the Messenger", description = "I am merely a field commander, {class}. The authority to act on this kind of information falls squarely on the shoulders of our leader, Nazgrel. You must take this missive to him in Thrallmar. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Nazgrel!", sourceObjective = "Take the Legion Missive to Nazgrel at Thrallmar in Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[10136] = { id = 10136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruel's Intentions", description = "Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, {name}. Terminate with extreme prejudice. \n\nHead west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the Horde reclaims Hellfire Peninsula. Let the Legion be damned.", sourceObjective = "Kill Arazzius the Cruel, then return to Nazgrel in Thrallmar.", progress = "Destiny calls, {name}. Arazzius the Cruel has eluded justice long enough. Let his death be a message to all those who would oppose the Horde.  You are next.", completion = "For generations to come, they will sing songs of this day, {name} - songs of your valor. I wish Thrall had been here to celebrate this victory with us. The Legion is undone - and Hellfire now belongs to the Horde once again! There may yet be hope for this ravaged world - and our peoples' place within it. \n\nLok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10137] = { id = 10137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by an orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.You will be able to choose one of these rewards:", sourceObjective = "Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Private Imarion's cage. Once you have freed Private Imarion, report to Lieutenant Amadi.", sourceObjectiveStatus = "unverified-source-field" }
quests[10138] = { id = 10138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Whose Orders?", description = "One thing is clear, {name}: we can't keep this up. The fel orcs have us surrounded and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war huddled behind Honor Hold's shattered walls and counting the days until our deaths at the hands of the fel orcs or the Legion.\n\nYou've done a remarkable job of sparing us from the brunt of the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating these attacks.", sourceObjective = "Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Lieutenant Amadi at Honor Hold's western guard tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[10139] = { id = 10139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispatching the Commander", description = "From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.\n\nThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.\n\nZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, {name}, but it would be wise to travel with allies.You will be able to choose one of these rewards:", sourceObjective = "Slay Force-Commander Gorax and report to Lieutenant Amadi at Honor Hold's western tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[10140] = { id = 10140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Honor Hold", description = "When you're ready, I'll arrange a flight straight to Honor Hold.\n\nFrom there, speak with Marshal Isildor and give him Duron's report.  He'll be happy to see another recruit from the homelands, and I'm sure the information in that report is important stuff!", sourceObjective = "Take a flight to Honor Hold and deliver Duron's Report to Marshal Isildor.", progress = "Thank the Light you made it here safely. Honor Hold needs all the seasoned warriors it can muster.", completion = "Our expedition to this forsaken, wreck of a world has almost ground to a halt, {name}. We encountered more resistance than we bargained for.\n\nAs if facing the Burning Legion again wasn't bad enough - there are horrors in this land unlike anything we've ever encountered.", sourceObjectiveStatus = "unverified-source-field" }
quests[10141] = { id = 10141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion Reborn", description = "While the Burning Legion invaded Azeroth, they were also at work here, in Outland.  We have tracked their movements over the years, but this latest activity, {class} - well, this is beyond anything we've seen.\n\nSeek out Sergeant Altumus near the eastern supply caravan. She has been monitoring the invaders and may have insights into their purpose.\n\nBe swift - and take care, {name} - the Burning Legion is not to be underestimated.", sourceObjective = "Speak with Sergeant Altumus at the East Supply Caravan just outside of Honor Hold, to the east.", completion = "Force Commander Danath may have misunderstood my request for reinforcements. You look capable, but... I asked for a full sized battalion!\n\nYou see, we have a bit of a demon problem...", sourceObjectiveStatus = "unverified-source-field" }
quests[10142] = { id = 10142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Anguish", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", sourceObjective = "Sergeant Altumus at the East Supply Caravan east of Honor Hold in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", progress = "Honor Hold is safe so long as the archers guard our skies.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth new dreadlords.\n\nNow for the bad news: I've got your new orders...", sourceObjectiveStatus = "unverified-source-field" }
quests[10143] = { id = 10143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Point", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. You'll see Expedition Point where a Legion base used to stand. Once there, you are to report to Forward Commander Kingston.\n\nNow move out!", sourceObjective = "Report to Forward Commander Kingston at Expedition Point.", completion = "Glad to meet you, soldier.\n\nEnough chatting... now listen up -- I have a vital mission for you and I want you to succeed... and survive!", sourceObjectiveStatus = "unverified-source-field" }
quests[10144] = { id = 10144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt Their Reinforcements", description = "You'll find the Legion front to our northeast, and spaced along it are portals used to gather reinforcements from throughout Outland. We, {name}, are going to destroy those portals!\n\nTake this primer.  Designed in Area 52, it uses the demons' own power as an explosive device!  Defeat Legion forces around Portals Grimh and Kaalez to gather demonic rune stones, use the primer to detonate the stones inside the portals... then watch the fireworks!!\n\nGo, {name}, and return to me when your mission is complete.", sourceObjective = "Defeat enemies around Portal Grimh and Portal Kaalez to gather Demonic Rune Stones.\n\nUse Kingston's Primer inside Portal Grimh and Portal Kaalez.\n\nReturn to Forward Commander Kingston with the remaining explosives.", progress = "I wish I could be there to watch the fire display.  Those explosives pack a big punch!", completion = "Well done, {name}.  Disabling those portals will stem the flow of Legion reinforcements for a long time!\n\nBut we can't rest yet...", sourceObjectiveStatus = "unverified-source-field" }
quests[10146] = { id = 10146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Murketh and Shaadraz Gateways", description = "Just west of the Dark Portal are two huge transporters: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into rubble!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Dabir'ee -- he'll put you on a gryphon and send you on your way.", sourceObjective = "Speak with Wing Commander Dabir'ee, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander Kingston at Expedition Point.", progress = "This is a vital mission, {name}.  It's one I would not trust to just anyone.", completion = "That will slow them down, there's no denying it! I think you just put me in an uncharacteristically good mood, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10147] = { id = 10147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Kill the Messenger", description = "Your handiwork is already causing the Legion great discomfort, {name}. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!\n\nWhat I ask of you next is more than I would ask of an ordinary soldier.\n\nThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, far north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.", sourceObjective = "Forward Commander Kingston at Expedition Point in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive.", sourceObjectiveStatus = "unverified-source-field" }
quests[10148] = { id = 10148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Be the Messenger", description = "I am merely a field commander, {class}. The authority to act on this kind of information falls squarely on the shoulders of our leader, Force Commander Danath Trollbane. You must take this missive to him in Honor Hold. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Danath!", sourceObjective = "Take the Legion Missive to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[10149] = { id = 10149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: End All, Be All", description = "Do you know what would have happened if you had not intercepted this missive, {name}?\n\n<Danath nods.>\n\nThe entirety of the Legion army in Hellfire would have been knocking on our door. There is no way that we could have survived such an assault.\n\nThere is only one way to make sure that these orders never reach the Legion Front. You must travel to the Pools of Aggonar, far northwest of here, and slay this Arazzius creature.\n\nDo this and I will grant you a commendation.You will be able to choose one of these rewards:", sourceObjective = "Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula has asked that you slay Arazzius the Cruel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10150] = { id = 10150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable trackers, Scout Makha, to track their movements, preparations and numbers, but she hasn't returned to report her findings.\n\nMakha was to focus her efforts on the northernmost camp along the Northern Rampart, near where it ends in the rocks. Find her, {name}. Without her information, we're sitting ducks.", sourceObjective = "Search the northernmost camp along the Northern Rampart for any trace of Scout Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10151] = { id = 10151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their orcish prisoner south for interrogation.\n\nShadow Hunter Ty'jin mentioned that the Northern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Scout Makha.\n\nJudging by the note's mention of interrogation, it seems the scout's fel orc captors see some value in keeping her alive. Pick up the trail before they decide to change their minds.", sourceObjective = "Travel south along the west side of the Northern Rampart and search the next camp for signs of Scout Makha", sourceObjectiveStatus = "unverified-source-field" }
quests[10152] = { id = 10152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Thrallmar.\n\nWith the town's garrison concentrating on its eastern walls, an attack from the west would be devastating. Thrallmar can only hope to hold out if the western forces are kept out of the battle.", sourceObjective = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10153] = { id = 10153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Scout Makha", description = "The tracks lead south from Makha's equipment, appearing to cross the Path of Glory. The roughness of the shallow ruts suggests that Makha's captors were in a hurry to move her to the next destination, but why?\n\nWas someone waiting there for her, perhaps Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Scout Makha, you're likely to find Warboss Nekrogg too.", sourceObjective = "Continue south across the Path of Glory to the Southern Rampart and search for where Warboss Nekrogg is holding Scout Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10154] = { id = 10154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planning the Escape", description = "Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.\n\nHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that human he's managed to capture.\n\nIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.", sourceObjective = "Kill a Shattered Hand Grenadier and bring his Crude Explosives to Scout Makha at Gor'gaz Outpost.", sourceObjectiveStatus = "unverified-source-field" }
quests[10155] = { id = 10155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by a fel orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.You will be able to choose one of these rewards:", sourceObjective = "Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Scout Makha's cage. Once you have freed Scout Makha, report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10156] = { id = 10156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Whose Orders?", description = "One thing is clear, {name}: we can't keep this up. The fel orcs have us pinned down and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war with our forces divided and locked in constant combat with the fel orcs and the demons of the Legion.\n\nYou've done a remarkable job of blunting the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating this offensive.", sourceObjective = "Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Stone Guard Ambelan at Spinebreaker Post.", sourceObjectiveStatus = "unverified-source-field" }
quests[10157] = { id = 10157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispatching the Commander", description = "From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.\n\nThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.\n\nZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, {name}, but it would be wise to travel with allies.You will be able to choose one of these rewards:", sourceObjective = "Slay Force-Commander Gorax and report to Shadow Hunter Ty'jin at Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10158] = { id = 10158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nShadow Hunter Ty'jin sent me here to keep an eye on the outpost and its strange inhabitants.\n\nSomething has changed these orcs, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Fight your way into Zeth'Gor and destroy any supplies you find there.", sourceObjective = "Destroy 6 piles of Bleeding Hollow Supplies and report to Stone Guard Ambelan at Spinebreaker Post.", sourceObjectiveStatus = "unverified-source-field" }
quests[10159] = { id = 10159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Thornfang Hill Clear!", description = "We've been fighting an ongoing battle to keep the pass through Thornfang Hill to the west clear of ravagers.  It would be bad if we were to become completely cut off from the refuge in Zangarmarsh.\n\nWe don't want to displace the creatures, but there seems to be little choice as their attacks on travelers through the area have become more aggressive.\n\nClear some of the ravagers out of there if you can.", sourceObjective = "Kill 8 Thornfang Ravagers and 8 Thornfang Venomspitters, and then return to Mahuram Stouthoof at the Cenarion Post in Hellfire Peninsula.", progress = "How fares your attempt to clear Thornfang Hill?", completion = "With the ravagers cleared, travelers to and from the Cenarion Refuge in Zangarmarsh should have an easier time of it.\n\nThe Cenarion Expedition is indebted to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10160] = { id = 10160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know your Enemy", description = "Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we're familiar with.  If these rumors are true then our forces, already stretched, may be taxed beyond their limit.\n\nI have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold.\n\nAnd {name} - be careful out there. You're heading into a dangerous new world.", sourceObjective = "Speak with Lieutenant Amadi at the old guard tower just west of Honor Hold.", completion = "<Lieutenant Amadi nods.>\n\nGood, we need all the help we can get. The increasing fel orc presence around the Southern Rampart concerns me. I sent out a scout to investigate, but he hasn't yet returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[10161] = { id = 10161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Case of Emergency...", description = "In the event of an emergency, it's always the pilot's job to keep a level head, especially when the only orders your co-pilot follows come from his stomach.\n\nThe good news is that we won't need to wait days for replacement parts to be imported. The bad news is that the \"spare\" parts got scattered from here to the Valley of Bones to the east.\n\nThe other bad news? The spare parts aren't so spare. They, uh, fell off during our rapid descent. Could you help me collect enough to get us off the ground again?", sourceObjective = "Collect 30 pieces of Zeppelin Debris and bring them to \"Screaming\" Screed Luckheed at the Zeppelin Crash.", progress = "Did you find enough of the parts? If not, I might have to use that frying pan Legassi keeps waving around. Then, I'd have to rename the zeppelin the \"Flying Skillet.\"", completion = "Some of this is in pretty bad shape, but there should be enough to work with here. With some creative engineering, I'm confident I can make it work!", sourceObjectiveStatus = "unverified-source-field" }
quests[10162] = { id = 10162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a wyvern and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Wing Commander Brack when you're ready for takeoff.", sourceObjective = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, {name}. Outstanding performance out there! Not even a scratch on the wyvern destroyers!", sourceObjectiveStatus = "unverified-source-field" }
quests[10163] = { id = 10163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a gryphon and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Gryphoneer Windbellow when you're ready for takeoff.", sourceObjective = "Wing Commander Gryphongar at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, {name}. Outstanding performance out there! Not even a scratch on the gryphon destroyers!", sourceObjectiveStatus = "unverified-source-field" }
quests[10164] = { id = 10164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and destroy Exarch Maladaar so that the spirits trapped inside can finally rest in peace.", sourceObjective = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and destroy Exarch Maladaar.", progress = "Save the spirits, {name}.", completion = "You've done it, {name}! The spirits are freed!\n\nAlthough I am without a material manifestation, I am still able to reward you with items from the spirit world. Use them with caution as such items are often volatile and can cause great harm to their user.", sourceObjectiveStatus = "unverified-source-field" }
quests[10165] = { id = 10165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercutting the Competition", description = "That Shaffar is a shrewd one - I'll give him that... He's managed to keep the Consortium out while he safely pillages this crypt for all it's worth. I have no faith in these imbeciles actually breaking through Shaffar's defenses so I'll make you a deal, {race}.\n\nEnter the Mana-Tombs and kill Nexus-Prince Shaffar. Bring me back his body wrap as proof of this deed and I'll reward you handsomely.", sourceObjective = "Nexus-Prince Haramad located outside of the Mana-Tombs wants you to kill Nexus-Prince Shaffar and bring Shaffar's Wrappings back to him.", progress = "I don't like to \"share.\"", completion = "Another competitor goes under... You do good work for a flesh beast, {race}. If you are ever in Netherstorm, look me up. I make my home at the Stormspire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10166] = { id = 10166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitebark's Memory", description = "This pendant brings back memories of a different time.  A better time.\n\nUnfortunately, memories are the last thing I need right now.\n\nI want you to bury this by the runestone in the Scorched Grove.  It was there that I first met the treant elder.  Put my old friend's memory to rest.", sourceObjective = "Larianna Riverwind wants you to place Old Whitebark's Pendant by the runestone at the Scorched Grove.", progress = "You've returned, {name}.  Haven't you done enough?", completion = "I no longer belong to this world and must admit defeat.  The land has forever changed and nothing will ever be the same.\n\nLeave the pendant here with me, {name}.  Maybe one day, long after the elves are gone, a new tree will grow on this very spot - amongst a burnt forest and the husks of dead treants.", sourceObjectiveStatus = "unverified-source-field" }
quests[10167] = { id = 10167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun...", description = "Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of Auchindoun was born.\n\nYou must venture to the Auchenai Crypts of Auchindoun and find this tomb. Slay the guardian of the crypt to release the captive spirit within. The spirit holds the key...", sourceObjective = "Travel to the Auchenai Crypts in the Bone Wastes of Terokkar Forest and slay Exarch Maladaar to free the spirit of D'ore.", progress = "<D'ore's spirit hums.>\n\nGreetings, {name}.", completion = "The memory is vivid, {name}. My energies were wholly drained from the crash. I was only a dim speck of void energies when the Prophet Velen and his draenei compatriots lifted my remains and brought them here. After much ceremony, my diminished form was laid to rest within this sarcophagus. I have been regenerating for nearly a thousand years. The cycle is almost complete...", sourceObjectiveStatus = "unverified-source-field" }
quests[10168] = { id = 10168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Soul Sees", description = "For several centuries, the spirits of Auchindoun coalesced into my darkened essence. Many of the catastrophes that befell this crypt were a direct result of my weakened state.\n\nRegrettably, there is nothing that can be done to stop this cycle. It is a facet of the naaru condition - without the void, the Light cannot exist.\n\nYour only recourse is to destroy the ancient spirits of Nagrand before they transform into creatures of the void. Use the soul mirrors found throughout this crypt to free them...", sourceObjective = "Locate a Soul Mirror somewhere in the Auchenai Crypts and use it to call forth a Darkened Spirit from Ancient Orc Ancestors in Nagrand. Destroy 15 Darkened Spirits so that the ancestors may rest in peace.\n\nReturn to Mother Kashur at the Ancestral Grounds when this task is complete.", progress = "<Mother Kashur is visibly upset.>\n\nThese naaru are wise beyond all manner of life on this world.", completion = "You have completed a long and dangerous journey, risking life and limb to ensure the safety of the Mag'har and the serenity of our ancestors. For this I am thankful beyond what words could convey.", sourceObjectiveStatus = "unverified-source-field" }
quests[10169] = { id = 10169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Gracefully", description = "The Aldor have gained the favor of the Sha'tar today.  As if that should come as any sort of surprise!\n\nWatch them showing off their fancy footwork a few feet away from A'dal.  Could they possibly put any more effort into sucking up to the naaru?\n\nHarbinger Haronem's marksman regiment is so dedicated, it even brings its own cooking pot to avoid taking long breaks for lunch.  This cannot go without retribution, {name}.\n\nI want you to pour this vial into their meal.  The results should be... comical.", sourceObjective = "Magister Falris in Shattrath wants you to take the Vial of Sedative Serum to the Terrace of Light and pour it into Haronem's Regiment Cooking Pot.", sourceObjectiveStatus = "unverified-source-field" }
quests[10170] = { id = 10170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Greatmother", description = "Return to Greatmother Geyah at Garadar with news of your victory, {name}. This will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be lifted from his malaise.", sourceObjective = "Return to Garadar and speak to Greatmother Geyah.", completion = "I want you to personally deliver this news to Garrosh.", sourceObjectiveStatus = "unverified-source-field" }
quests[10171] = { id = 10171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inconsolable Chieftain", description = "You have done so much for the Mag'har, {name}. Your accomplishments are known to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.", sourceObjective = "Greatmother Geyah at Garadar has asked that you speak with Garrosh.", completion = "Everyone is proud. Proud that our people will live to see another winter. But beyond that? What is there?\n\nMaybe you should lead this clan, {name}. Maybe then I will be allowed to die when the Greatmother passes. Allowed to finally erase the shame of my family name. I long for such peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[10172] = { id = 10172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Is No Hope", description = "You are an honorable {race}, {name}. You have done much for the Mag'har. No one could ever deny your service to my people. Alas, the time of the Mag'har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs.\n\nPlease, {name}, return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.", sourceObjective = "Speak to Greatmother Geyah and tell her what Garrosh told you.", progress = "<Greatmother Geyah is lying down.>", completion = "<Tears stream down Greatmother Geyah's face.>\n\nSeek out your warchief. Tell him that I await him here...", sourceObjectiveStatus = "unverified-source-field" }
quests[10173] = { id = 10173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archmage's Staff", description = "Allow me to introduce myself, {class}.\n\nI am Ravandwyr, apprentice to the Archmage Vargoth.\n\nMy master is... indisposed, shall we say. I am here on a matter of great importance.\n\nThe Arklon Ruins southeast of the city are a hotbed of Burning Legion activity. Their purpose in the ruins concerns neither me nor my master, but their leader, Ekkorash, possesses the archmage's staff.\n\nThis conjuring powder will allow you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the ruins.", sourceObjective = "Retrieve Archmage Vargoth's Staff from Ekkorash the Inquisitor and bring it to Ravandwyr in Area 52. To bring Ekkorash out of hiding, sprinkle the Conjuring Powder on the brazier in the center of the ruins.", progress = "I will not rest until Archmage Vargoth's staff is restored to him. Were you able to wrest it from the demon's grasp?", completion = "Ah, so you managed to recover the staff. Impressive, {name}. Perhaps you are the one I've been looking for.\n\nOh yes, your reward...\n\n\n\nNo doubt you had higher expectations, but that too will come with time. For now, consider opportunity the true reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10174] = { id = 10174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse of the Violet Tower", description = "Now, you will be able to use the archmage's staff to contact him.\n\nHe resides in the Violet Tower, on an 'island' to the southeast. The tower is both sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, keeping me apart from my master.\n\nThe staff's magic can penetrate the tower's defenses, but only if invoked by one outside the Kirin Tor.\n\nTake the archmage's staff and use it to conjure his image. Tell him what has happened and that I have not completely failed him.", sourceObjective = "Use Archmage Vargoth's Staff to make contact with Archmage Vargoth.\n\nIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement.\n\nProvided item:", completion = "<Archmage Vargoth's image examines you as you convey Ravandwyr's message.>\n\nRavandwyr has everything a master can expect of his apprentice. When I gave him the staff and told him to flee, I hoped that he would use it to find help and free me once Kael'thas's forces withdrew from the tower. Since then, I have learned a great deal about the nature of the curse.\n\nIt can be broken, {name}, but it will require your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10175] = { id = 10175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrall, Son of Durotan", description = "Return to your world, {name}. Go to my grandchild and tell him that his blood is here - on this shattered world.\n\nTell him that his father's legacy lives on.\n\nTell him everything...", sourceObjective = "Venture to Orgrimmar and deliver Geyah's message to Thrall.", completion = "<Thrall's voice takes on the hollow essence of a storm cloud.>\n\nI... I have a grandmother? She lives?", sourceObjectiveStatus = "unverified-source-field" }
quests[10176] = { id = 10176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ar'kelos the Guardian", description = "Now that you've gathered all the items I'll need to break Kael'thas's curse, one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane golem, known as Ar'kelos, at the bottom of the tower.\n\nYou must defeat Ar'kelos in order allow me to work magic within the tower again.\n\nWhen you enter the Violet Tower, the curse will begin to affect you.\n\nOnce you have defeated Ar'kelos, ascend the tower and assist me in making preparations for the ritual.", sourceObjective = "Enter the Violet Tower at the center of Kirin'Var Village and defeat Ar'kelos, then speak with Archmage Vargoth.", progress = "At last, we meet.", completion = "You have done well, {name}. Destroying the dampening field will make it much easier for me to prepare the magic that will lift the tower's curse at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[10177] = { id = 10177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the entrance of the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", sourceObjective = "Report to Field Commander Mahfuun at the entrance to the Shadow Labyrinth at Auchindoun in Terokkar Forest.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!", sourceObjectiveStatus = "unverified-source-field" }
quests[10178] = { id = 10178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Spy To'gun", description = "To'gun, the fool!  We're barely holding off the attacks here, and he goes back in to get more information and try to save the other spies!\n\nI don't know whether to love him or kill him!\n\nThe Shadow Council must have used magic to ferret us out, because all of our spies had to get out of there in a hurry.  Most of us didn't make it.\n\nPlease, if you're brave enough to enter the Shadow Labyrinth, will you keep an eye peeled for To'gun?  It's been a while, and I fear the worst.", sourceObjective = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", completion = "What?  Grik'tha sent you in here after me?\n\nI don't know whether to be touched or call her a fool!\n\nDo you think you could help me get out of this cage?  It's a bit cramped.", sourceObjectiveStatus = "unverified-source-field" }
quests[10179] = { id = 10179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Custodian of Kirin'Var", description = "When it became clear that our expedition was trapped in Outland with no way to return to Azeroth, the Kirin Tor contingent traveled to the Plains of Farahlon and built Kirin'Var village. I left the administration of the town in the hands of Custodian Dieworth, but when Kael'thas and his forces sealed me in the Violet Tower, I lost contact with the custodian.\n\nSearch for him in Kirin'Var Village and help him in any way you can, {name}. I'm certain he's got his hands full in the aftermath of the attack.", sourceObjective = "Speak with Custodian Dierworth in Kirin'Var Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[10180] = { id = 10180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Stay Away", description = "I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own.\n\nHe was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time.\n\nI admire his desire to free his sister, but he's not going to be able to do it without help.\n\nFind Isfar and have a word with him, {name}. If you can't persuade him to come back, perhaps you could help him rescue Lakka?", sourceObjective = "Speak with Isfar, who can be found near the entrance to the Sethekk Halls in Auchindoun.", completion = "I should've suspected he would send you after me. He tried to talk me out of returning to the Sethekk Halls, but I couldn't live with myself if I allowed Lakka to die in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[10182] = { id = 10182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle-Mage Dathric", description = "The sword is of exceptional quality, finely crafted and perfectly balanced for a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the weapon's pommel.\n\nTurning the weapon over in your hands, you notice a sense of wrongness radiating from the metal, as if the item is torn between two worlds. Could this be the item anchoring Battle-Mage Dathric's spirit to this world?\n\nPerhaps returning it to its proper place can break the bond, freeing Dathric's spirit to rest at last.", sourceObjective = "Locate Battle-Mage Dathric's quarters in Wizard's Row and return the blade to his weapon rack. Then, speak with Custodian Dieworth at Kirin'Var Village.", progress = "What have you found, {name}?", completion = "You've done well, {name}. I can no longer sense any restlessness in Dathric's spirit. I would give much for the opportunity to speak to him one more time, but it is enough that he is finally at rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10183] = { id = 10183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off To Area 52", description = "I'm out here studying the nether - the ethereal currents and all that.  This is an ideal spot away from the lights and hubbub of town.  Isn't this bridge great?  If I could just keep this junk working.\n\nHey, you know, if you're looking for work there's plenty at Area 52!  It's just up the path and take a right at the fork in the road.\n\nWhy don't you deliver my latest research notes to Rocket-Chief Fuselage?  I'm sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!", sourceObjective = "Deliver the Netherologist's Notes to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Busy, busy.  No time to waste!  There's a rocket ship to be built!\n\nWhat do you want?", completion = "Oh, Coppernickels finally decided to report his findings, did he?  Lazy scientists!\n\nWhat's this?\n\n<The chief riffles through the notations a few times, clearly with a look of disbelief.>\n\nHe says here that the violent nether-energies flowing through the Netherstorm are going to rip everything to shreds in only a few months.\n\nThat's inconvenient - now we'll have to move up the time-table on building the rocket ship!", sourceObjectiveStatus = "unverified-source-field" }
quests[10184] = { id = 10184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malevolent Remnants", description = "Most of the spirits in the village are little more than pale remnants of Kirin Tor mages. They retain no knowledge of their former selves and wander the ruins in blind anger.\n\nIt wasn't always like this, though. In the immediate aftermath of the attack, the spirits were restless, but not spiteful. With the passage of time they have only grown more aggressive. I dare not venture into the southern part of the village, for they will not spare even me. Quiet them and let us hope it will purge their anger.", sourceObjective = "Custodian Dieworth at Kirin'Var Village wants you to defeat 20 Severed Spirits in Kirin'Var's Town Square.", progress = "It pains me to know there is so little to be done for our comrades.", completion = "<Custodian Dieworth shakes his head gently.>\n\nIt is not what they deserved, but it is the best we can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10185] = { id = 10185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fate Worse Than Death", description = "After the blood elves leveled Kirin'Var Village, they started the construction of a large building to the northwest. Without the expertise of the archmage, we can't say for certain what's going on there.\n\nOne thing is clear, though. The blood elf activities have unleashed a tide of ravenous mana elementals on the village. They seem drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to continue.", sourceObjective = "Kill 10 Mageslayers and 10 Mana Seekers and return to Custodian Dieworth at Kirin'Var Village.", progress = "Have you managed to clear out some of the mana creatures from the village ruins?", completion = "<The custodian looks dismayed.>\n\nI can already see the next wave coming over the horizon. Culling them will work for the time being, but more permanent measures are needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10186] = { id = 10186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Hired!", description = "Let me be the first to welcome you aboard, Junior Technician 3rd Grade {name}!\n\nWe're building my masterpiece out here - the X-52 Nether-Rocket!\n\nBut first we need to get all of the parts and fuel for it.  That's where you come in.\n\nTo start, I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix.  The draenei had crystals coming out of their ears!\n\nSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.", sourceObjective = "Collect 10 Etherlithium Matrix Crystals and return them to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Does it look like the X-52 Nether-Rocket is ready for liftoff?  Am I cruising the Twisting Nether in the comfort of my command chair?  Exploiting strange new worlds?  Seeking out new technology and business opportunities?  Boldly going where no goblin has gone before?\n\nNo!\n\nSo, I hope you have those crystals that I sent you after.", completion = "Gah!  Those look rough.  Maybe we can use them in the tertiary engine manifold chamber?\n\nStill, a good job Junior Technician 3rd Grade!  You'll make 2nd Grade in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10187] = { id = 10187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message for the Archmage", description = "Although things are grim here, it heartened us quite a bit to hear from you that the archmage has not forgotten the village's plight.\n\n<The custodian glances up at the tower.>\n\nIt's ridiculous, isn't it? Sometimes it seems all that separates us is a wall of mere stone. The wall of magic is easy enough to forget.\n\nIf you would be so kind, ascend the tower and let Archmage Vargoth know that we are making progress with the village and will soon have a plan to ward off the mana creatures.", sourceObjective = "Speak to Archmage Vargoth at the top of the Violet Tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[10188] = { id = 10188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sigil of Krasus", description = "Before we departed Azeroth all those years ago, the Kirin Tor entrusted our expedition with a powerful artifact, the Sigil of Krasus. It was a great boon to us in our battle against the orcs and it could play a key role in helping me break the enchantment that imprisons me.\n\nHowever, when Kael'thas divested me of my possessions, he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he truly realized what he had in his possession, he wouldn't have given it away so easily.", sourceObjective = "Retrieve the Sigil of Krasus from Spellbinder Maryana at Manaforge Coruu, northwest of the Violet Tower. When you have gained the sigil, use Archmage Vargoth's Staff to project an Image of Archmage Vargoth and inform him of your progress.\n\nIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement.", progress = "If I am to be free of the tower's curse, I must have the sigil.", completion = "Ah, it is as magnificent as I remembered. Can you not feel the power radiating from it?\n\nOf course, there is much more to be done, but you have my deepest thanks for restoring the sigil to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10189] = { id = 10189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge B'naar", description = "You may have noticed one of Kael's manaforges on your way here.  You know, the large purple buildings sucking energy from the sky?\n\nWe were sent here by the Sha'tar to investigate them.  You can help our information gathering efforts by obtaining a personnel roster.  Giving us an idea of who's there and what they do will prove to be invaluable information.\n\nWe believe Captain Arathyn, leading a ballista team just outside of Manaforge B'naar, is in possession of one such roster.  Obtain it for us.", sourceObjective = "Spymaster Thalodien at Area 52 wants you to go to the outskirts of Manaforge B'naar and retrieve the B'naar Personnel Roster from Captain Arathyn.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you obtain the items I asked of you, {name}?", completion = "Excellent!  With this roster we can make more educated decisions when targeting Kael's followers at the manaforges.\n\nIt's too bad, I was beginning to take a liking to killing his lackeys indiscriminately.", sourceObjectiveStatus = "unverified-source-field" }
quests[10190] = { id = 10190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recharging the Batteries", description = "I have the very important task of collecting the machinery inside these ruins, but I'm having a problem keeping all of my bots charged up.\n\nThe phase hunters - those wyrm-looking things - have lots of energy!  You can find them all over the edges of this island, floating in from the nether.\n\nFill the battery on this recharging blaster by using it on a phase hunter when they're very weak, and then finish it off to soak up the last of its energy.", sourceObjective = "Use the Battery Recharging Blaster on enough Phase Hunters to get the Battery Recharge Level to 10. Then return it to Bot-Specialist Alley at the Ruins of Enkaat in the Netherstorm.", progress = "Have you recharged the battery in that blaster yet?", completion = "Hey, watch where you're pointing that thing!  You've got it set to 'Kill'!!!\n\nIt looks like you've recharged the battery, and then some.  This'll help immensely to keep these guys going.", sourceObjectiveStatus = "unverified-source-field" }
quests[10191] = { id = 10191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark V is Alive!", description = "Greetings, {race}.  I am charged up and fully functional.\n\nThere are fragile draenei machines in these ruins, which I must retrieve.  I am equipped with delicate servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers.  Handling them with care will not be an issue.\n\nHowever, the ghosts that haunt these ruins will likely attack, so I will need you and your friends along for protection.", sourceObjective = "Escort the Maxx A. Million Mk. V through the Ruins of Enkaat and back out to safety. Then speak with Bot-Specialist Alley just outside the Ruins of Enkaat in the Netherstorm.", progress = "Back so soon?\n\nIs everything okay with the Maxx A. Million Mk. V?!", completion = "You did it!  You did it!  I could just kiss you!\n\nOh, darn... the Maxx A. Million Mk. V is out of juice again.  Ah well, he had enough to get the job done, and that's what counts!\n\nRocket-Chief Fuselage will be pleased to get these draenei machines hooked up inside the X-52 Nether-Rocket!  That means a promotion for me!  I'm so happy, I just have to give you a reward!\n\nHere, take your pick from one of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[10192] = { id = 10192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus's Compendium", description = "The Kirin Tor sent one other of Krasus's possessions with our expedition. It was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it lent us a much-needed advantage in the war.\n\nBefore Kael'thas and his forces laid siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice intent on studying necromancy. The apprentice and his followers divided and studied the text in secret, locking themselves inside their houses in the southern part of town.", sourceObjective = "Reclaim Krasus's Compendium - Chapter 1, Krasus's Compendium - Chapter 2, and Krasus's Compendium - Chapter 3 from Kirin'Var Village's Town Square. Use Archmage Vargoth's Staff to contact the archmage once you have the chapters.\n\nIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement.", progress = "Have you brought the book?", completion = "<Archmage Vargoth's image seems to inspect the compendium.>\n\nIt's a little worse for the wear, but considering the treatment it's been through, it's a miracle all of it survived. Safeguard it, {name}. Without it, we stand little chance of being able to break the tower's ward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10193] = { id = 10193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Value Targets", description = "Based on the roster information, we know that the brains of the manaforge operations are the warp-masters and warp-engineers.  It is they who oversee the retrieval of a so called \"warp-energy\" by the manaforge and its delivery to a remote destination via a system of underground pipes.\n\nThe only other specialists in the area are geologists.  Everyone else is either part of the military or a magister crony; both easily replaced.\n\nGet in there and kill Kael's specialists; that's what'll hurt him the most.", sourceObjective = "Spymaster Thalodien at Area 52 wants you to go to Manaforge B'naar and slay 2 Sunfury Warp-Masters, 6 Sunfury Warp-Engineers and 8 Sunfury Geologists.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "How goes it, {name}?  Got any news?  What have you done for me lately?", completion = "You're one reliable fellow, {name}.  If there's one thing I like more than killing Kael's lapdogs, it is having someone else do it for me.\n\nLess blood on my clothes that way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10194] = { id = 10194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealth Flight", description = "While you were gone, my men uncovered another one of these manaforges.  It is east of here and is known as Manaforge Coruu.\n\nTwo of my best spies have arranged a secret landing spot outside of the manaforge.  You are to help them infiltrate Kael's forces and obtain whatever information you can.\n\nSpeak to Veronia just outside the city walls; she's arranged for a windrider that will take you to Manaforge Coruu.  Once there, speak to Caledis Brightdawn; he will brief you on your mission.", sourceObjective = "Speak to Veronia outside Area 52 and fly to Manaforge Coruu.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "Arranging for your flight wasn't cheap.  Let's hope you have what it takes to get the job done.", sourceObjectiveStatus = "unverified-source-field" }
quests[10195] = { id = 10195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercenary See, Mercenary Do", description = "Ever since you brought that first batch of feathers and I completed Bertelm's hat, all the other mercenaries have been clamoring for their own, including Thander. It told them I'd get right on it, but I'm going to need a steady supply of arakkoa feathers for the project.\n\nI'll gladly accept any you happen to gather in your adventures in the forest.", sourceObjective = "Bring 30 Arakkoa Feathers to Ros'eleth at the Allerian Stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10196] = { id = 10196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Arakkoa Feathers", description = "I've had some success drawing the arakkoa spirits closer to me, but they are still very shy. Perhaps if I improve my disguise, they will be more willing to approach me in the trance.\n\nTo do that, though, I'll need more feathers like the ones you've already brought me. If you get any more of the feathers, I'd be very happy to take them off your hands.", sourceObjective = "Bring 30 Arakkoa Feathers to Malukaz at Stonebreaker Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10197] = { id = 10197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Convincing Disguise", description = "Infiltrating the ranks of Kael's army will not be an easy task.  With my knowledge of illusionary magic I could pass you off as one of Kael's followers, but there are certain details in their uniforms I could not replicate.\n\nBring me a set of their robes, a pair of their gloves and a Sunfury guardsman medallion.  This will make the results of my magic much more convincing.", sourceObjective = "Obtain a set of Sunfury Arcanist Robes, one pair of Sunfury Researcher Gloves and a Sunfury Guardsman Medallion and bring them to Caledis Brightdawn at Manaforge Coruu in Netherstorm.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you obtained the outfit pieces I asked of you?", completion = "Excellent!  When I'm through with you, you will be able to slip among the Sunfury ranks unnoticed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10198] = { id = 10198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Information Gathering", description = "I've prepared a uniform with the pieces you obtained.  It is magically enhanced to complete the illusion.\n\nWe spotted Commander Dawnforge going in to meet Arcanist Ardonis a few minutes ago.  He had a full retinue of guards with him, so whatever they're discussing is bound to be incredibly important; see if you can catch any of it.\n\nOh, I almost forgot.  You'll want to stay away from the arcane golems patrolling the manaforge.  They will see right through the illusion.", sourceObjective = "Use the Sunfury Disguise, go into Manaforge Coruu and listen to the conversation between Commander Dawnforge and Arcanist Ardonis. Report back to Caledis Brightdawn after completing this task.\n\nCompleting tasks for the Scryers will cause your Aldor reputation level to decrease.", progress = "How goes the eavesdropping, {name}?  You'd best hurry.  I'm getting antsy here.", completion = "Manaforge Duro is in trouble?  I'm sure Thalodien will love to hear the news.  Let's wrap up the job here first.", sourceObjectiveStatus = "unverified-source-field" }
quests[10199] = { id = 10199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Little Extra Kick", description = "So, I'm just missing the one ingredient that'll give my concoction that little extra kick that it needs.\n\nThe sting of the nether rays, roaming around near the shaleskin flayers, delivers quite a punch.  Bring me some of their stingers and I'll extract the venom right out of them!\n\nI'm certain the results will be explosive!", sourceObjective = "Obtain 5 Nether Ray Stingers for Boots at Area 52 in the Netherstorm.", progress = "If I can drain the venom from enough of those nether ray stingers, I think we might just have the most explosive fuel ever devised!", completion = "Wow!  Alright, now we're talking!\n\nLet me just take those little beauties and squeeze the badness right out of them.  This should make a rocket fuel brew that'll blow everyone's socks off!\n\nHere, just let me mix the shale oil and this stinger venom together, and we'll see what happens....", sourceObjectiveStatus = "unverified-source-field" }
quests[10200] = { id = 10200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Thalodien", description = "It would be best if this information got back to Thalodien as soon as possible.  I'll stay here and cover our tracks.\n\nIt wouldn't do us much good to have Kael'thas find out what we were snooping around here.  Secret information is always better if your enemy doesn't know you have it.", sourceObjective = "Return to Spymaster Thalodien at Area 52 in Netherstorm.", completion = "You do not cease to amaze me, {name}.  That was quite the feat of stealth you pulled off at Manaforge Coruu.", sourceObjectiveStatus = "unverified-source-field" }
quests[10201] = { id = 10201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Now, the Moment of Truth", description = "The oil is finally ready for its first test. It seems heavy enough to serve as a high quality weapon oil.\n\nThe only way to find out is to have a professional try it out. See Grek over there by the wanted posters? Sure, he's no poet, but the orc knows his way around a weapon!\n\nTake a sample of the oil to him and ask him to use it on his weapon. After he's had a chance to test it out, let me know what he thinks of it.", sourceObjective = "Find Grek and ask him to try it on his weapon. Once he's tried out the oil, return to Rakoria with the results.", progress = "Well, do you have the test results?", completion = "<You tell Rakoria the results of the test and she throws her head back, laughing.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10202] = { id = 10202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Defector", description = "We've recently been contacted by a Sunfury magister who wishes to join our ranks and swears he has information we're in need of.  We've checked our informants to make sure he's not a double agent and he checks out.\n\nHe's stationed in Manaforge Ara which makes communication difficult.  Talk to him and see what he knows.  If he's half as useful as he claims to be, we'll be able to put him to good use.", sourceObjective = "Go to Manaforge Ara and speak to Magister Theledorn.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "It's about time you showed up.  I was beginning to wonder if the Scryers were interested at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10203] = { id = 10203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invaluable Asset Zapping", description = "See the fissure running through Area 52?  We did that!  <grin>\n\nIt's yielding up all sorts of goodies for the X-52 Nether-Rocket, but we're running short on equipment.\n\nWe had an operation at the Arklon Ruins to the southeast until the Burning Legion moved in.  I need you to take this Ultra Deconsolodation Zapper to the ruins.  Use it to beam our gear back to Lead Sapper Blastfizzle down in the fissure.\n\nJunior Technician 3rd Grade {name}, this is your chance for that promotion.  Don't blow it!", sourceObjective = "Use the Ultra Deconsolodation Zapper to beam the Hyper Rotational Dig-A-Matic, Servo-Pneumatic Dredging Claw, Multi-Spectrum Terrain Analyzer, and the Big Wagon Full of Explosives back to Area 52. Then report to Lead Sapper Blastfizzle at the eastern end of the fissure that runs through Area 52 in the Netherstorm.", progress = "Isn't this place great?  And everyday yields something new and exotic!\n\nWhat a stroke of luck that we nearly destroyed the town digging down here.", completion = "You must be the one that zapped all of that sapping equipment back to us here from the ruins!  Hooray for you!\n\nI've already reallocated the equipment out to our other locations.  Now we'll be able to expedite our fissure operations on this whole island by an order of magnitude!  The nether-rocket will be completed in no time!\n\nHmmm, that's odd.  Wait a minute, did you say that you sent four things back to us?  I only got three...", sourceObjectiveStatus = "unverified-source-field" }
quests[10204] = { id = 10204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgem Crystals", description = "Kael's magisters have refined their usage of mana crystals to the point where they can siphon large amounts of energy in a matter of seconds.\n\nThey do this by attuning smaller bloodgem crystal shards to larger, fully charged ones.\n\nGo to Manaforge B'naar and obtain one of these shards from a Sunfury magister and use it to siphon energy from one of the larger crystals.\n\nReturn to me so that I may study the effects of the aura.  Do not worry; any side effects should be temporary.", sourceObjective = "Magistrix Larynna wants you to go to Manaforge B'naar and obtain a Bloodgem Shard from a Sunfury Magister. Use this shard near the larger Bloodgem crystals and return to her at Area 52.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you investigate the bloodgems used by the Sunfury magisters, {name}?", completion = "Hmmm... just as I suspected.\n\nExposure to this level of raw energy greatly magnifies our innate addiction to magic.\n\nI'm not surprised Kael gets away with what he does; all his subordinates are basically drunk on this.", sourceObjectiveStatus = "unverified-source-field" }
quests[10205] = { id = 10205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warp-Raider Nesaad", description = "Warp-Raider Nesaad must be dealt with!  I have no idea how he survived my attack, but he cannot be allowed to continue his operation out there.\n\nGo back and take out Nesaad.  He keeps a small ethereal camp near the southwestern corner of the Heap.\n\nDon't fail like I did, {class}.", sourceObjective = "Kill Warp-Raider Nesaad and then return to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", progress = "It's over then?  Warp-Raider Nesaad is dead?", completion = "It's a relief to hear that scum is finally dealt with.  You do good work, {name}... may I be so forward as to call you by your name?\n\nIf you're willing, I have another task that needs doing.  One that is very important and someone of your obvious skill should be able to handle with ease.", sourceObjectiveStatus = "unverified-source-field" }
quests[10206] = { id = 10206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick Your Part", description = "Those ethereal clowns are as opportunistic as us, I'll give them that.  But no one, and I mean NO ONE, moves in on a B.O.O.M. claim!\n\nThe Heap to the south is ours!\n\nIf we're to finish the X-52 Nether-Rocket, we're going to need all of the new tech that we can get our hands on.  And since the ethereals are stealing from us, I think it's only fair that we repay them in kind.\n\nWhy don't you head down there and see if you can acquire some of their technology out from under their noses!", sourceObjective = "Collect 10 pieces of Ethereal Technology and return them to Papa Wheeler at Area 52 in the Netherstorm.", progress = "Back with their tech so soon?  You better not just be pulling my leg here, {class}.\n\nThe success of the X-52 project out here depends upon you getting us that stuff a.s.a.p.!", completion = "Hehe, ethereal suckers!\n\nThanks for getting us these parts, {class}.  I bet we can just hook these babies right up inside the rocket.  I wonder what they do?  Should be fun finding out!\n\nHmm, let me see if I can dig up some pocket change to throw your way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10207] = { id = 10207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Base: Reaver's Fall REUSE", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Foward Commander To'arch.\n\nNow move out!", sourceObjective = "Report to Forward Commander To'arch at Reaver's Fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10208] = { id = 10208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt Their Reinforcements", description = "Directly east of here is the Legion Front.  Spaced across the front are infernal portals and gateways, used to bring reinforcements to Hellfire Peninsula and throughout Outland. We're going to destroy those portals!\n\nTake these primers.  Designed in Area 52, they use the demons' own power as an explosive!  Defeat Legion forces around Portals Xilus and Kruul to gather demonic rune stones, use the primer to detonate four stones inside the portals, and watch!  Return to me when your mission is complete.", sourceObjective = "Defeat enemies around Portal Xilus and Portal Kruul to gather Demonic Rune Stones.\n\nUse To'arch's Primer within Portal Xilus and Portal Kruul.\n\nReturn to To'arch with To'arch's Primers at Reaver's Fall in Hellfire Peninsula.", progress = "The Legion won't be prepared for the surprise you have for them, eh {name}?", completion = "Well done!  I could almost feel the tremors of the explosions from here!\n\nNow, we have one more bombing mission for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[10209] = { id = 10209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoner Kanthin's Prize", description = "The next thing we must do is reclaim my familiar, Glacius, from the blood elf summoner who holds it captive. Summoner Kanthin was one of the most senior magisters in the force Kael'thas sent to decimate Kirin'Var. It's only natural that he would claim my familiar as a kind of trophy.\n\nI'm certain that Kanthin, fool that he is, has tried to compel Glacius to serve him. My scrying has revealed that Kanthin is now stationed at 'Manaforge Duro,' if that terminology has any meaning for you.", sourceObjective = "Defeat Summoner Kanthin at Manaforge Duro, on the island to the north of Sunfury Hold, and reclaim the Stone of Glacius from him. When you have obtained the stone, use Archmage Vargoth's Staff to contact the archmage.\n\nIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement.", progress = "Have you secured the Stone of Glacius?", completion = "<You're not sure whether it's just distortion, or the archmage really is smiling.>\n\nWith the last of my possessions restored, I have everything I need to break through Kael'thas's magic. I'll begin working the spell right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[10210] = { id = 10210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A'dal", description = "Welcome to Shattrath City, {class}.  This might be the one place in all of Outland where you'll find any semblance of safety.\n\nA group of naaru known as the Sha'tar drove the demons away from here.\n\nIf you've never met a naaru, you ought to see A'dal inside the Terrace of Light.  The leader of the Sha'tar is an awe-inspiring sight if I ever saw one.  Sure is a change of pace from anything else in this bleak land.", sourceObjective = "Speak to A'dal, the leader of the Sha'tar, in the center of the Terrace of Light.", completion = "<The light that filled your senses as you approached A'dal intensifies as you address him.  Melodic chimes continue to ring within your head.>\n\n<You are safe here.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10211] = { id = 10211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "City of Light", description = "Do not burden A'dal with petty inquisitions, {class}.  That just might be the most powerful being you ever come face to face with.\n\nYou do not look familiar.  I suppose you want to learn about the city?\n\nYou'll have to excuse me if I don't give you a tour myself, but I'm a bit busy discussing strategy with A'dal.  Perhaps you'll find a summoned servant acceptable in my stead?  Excellent!", sourceObjective = "Follow Khadgar's servant and listen to its story. Return to Khadgar after completing this task.", progress = "The stories of men are ephemeral, {name}.  The stories of cities last well into the years.", completion = "I hope you learned a thing or two about Shattrath, {name}.  It might take some time for things to sink in.", sourceObjectiveStatus = "unverified-source-field" }
quests[10212] = { id = 10212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero of the Mag'har", description = "I must set things in order before I leave. Return to the Greatmother and tell her that her grandson comes.", sourceObjective = "Return to Greatmother Geyah at Garadar in Nagrand.", completion = "You are truly the hero of the Mag'har, {name}. If not for you, we would have surely been overrun by the ogres and Broken.\n\nWe are a poor people but we do have some artifacts of power. Please, I insist that you take from our coffer.", sourceObjectiveStatus = "unverified-source-field" }
quests[10213] = { id = 10213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Crash", description = "When I was wounded in the wastes I saw a goblin zeppelin crash.  It went down to the northwest, beyond the Expedition Armory. \n\nThe zeppelin was on fire.  Shrieking, burning goblins were falling like bombs from the sky.  Of course I was in a lot of pain and I had lost a lot of blood.  I may have imagined the whole thing.\n\nIf you can find any survivors, we can offer them sanctuary here at Spinebreaker Post.", sourceObjective = "Search for crash survivors.", completion = "We were shot down by the Burning Legion, even though we waved a flag of truce.  Who knew the Burning Legion was so mean? \n\nWe cannot come with you to Spinebreaker Post.  We need to repair our zeppelin and be on our way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10214] = { id = 10214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disurbances coming from the mine, but that's the least of my problems.\n\nIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?", sourceObjective = "Kill 15 Gan'arg Sappers and return to Foreman Razelcraz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10216] = { id = 10216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety Is Job One", description = "Shaffar's ethereals have completely blocked us out of the Mana-Tombs. Thankfully, I've got a plan. While we can't go in through the front door, there are sure to be several transporters inside.\n\nI want you to clear the way for my crew first and then I want you to activate one of their transporters to teleport us inside.\n\nActivate the teleporter in the chamber right before Shaffar's chambers when the way has been cleared. Don't worry, I'll make it worth your while...", sourceObjective = "Artificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.\n\nOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it.", progress = "This device has over a dozen buttons, none of which look familiar to you.", completion = "<You close your eyes and press a button.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10218] = { id = 10218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Else's Hard Work Pays Off", description = "Who were you expecting!? That idiot Morphalius was 'de-prioritized.' Now I'm here to clean up his mess. All I need from you is to watch my back as I go through Shaffar's ether gatherers and suck them dry of all that they have collected. If I successfully complete my mission, Haramad himself will reward you!\n\nWhat do you say? Escort me through the Mana-Tombs and then collect some incredible treasure? You already did most of the work anyway! Nothing's alive back behind us, right?", sourceObjective = "Escort Cryo-Engineer Sha'heen safely through the Mana-Tombs so that he can gather the ether held inside Shaffar's ether collectors.\n\nReport to Nexus-Prince Haramad located outside the Mana-Tombs at the Consortium encampment should you succeed.", completion = "Seeing as how this was Morphalius's idea, I decided to give him his old job back. Well done little flesh beast. Well done, indeed!\n\nRemember, if you're ever looking for work and happen to be in Netherstorm, come find me at the Stormspire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10220] = { id = 10220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Listen", description = "I was sent here to make contact with the Unyielding spirits.  These once proud Alliance soldiers were defeated long ago, and now their cursed spirits haunt the ruins to the west.  \n\nIf they would only join us we would gain a powerful ally.  Imagine, a legion of undying warriors to use against our enemies.  But these undead are mad with hatred and will not listen to me.  \n\nPerhaps they can be forced to join us.", sourceObjective = "Mordiba wants you to defeat 12 Unyielding Footmen, 8 Unyielding Knights, and 6 Unyielding Sorcerers at the Expedition Armory to the west of Spinebreaker Post.", progress = "Have you taught the Unyielding the consequences of defying the Forsaken?", completion = "The Unyielding have felt the strength of the Horde.  No doubt they will soon be in the mood to listen to my proposed alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10221] = { id = 10221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dr. Boom!", description = "{name}, my former protege, Sparky Uberthruster, wouldn't wear his helmet while down here and one day transformed into the infamous Dr. Boom!\n\nAnd he stole off to the northeast with most of our sapping equipment!  He and his Boom Bots have been a menace to Area 52 ever since.\n\nI need you to go to his Camp of Boom just outside of town and put an end to him!  Use these Boom's Doom bombs to take him out.\n\nAnd make sure not to get too close to him or his Boom Bots!", sourceObjective = "Kill Dr. Boom and return with the good news to Lead Sapper Blastfizzle at Area 52 in the Netherstorm.", progress = "Have you saved us from the depredations of Dr. Boom?  I promise this time there won't be any exploding wagons, though that was a lot of fun!\n\nWe really should do that more often.", completion = "I'll always miss Sparky.  <sniff>  But we'll all sleep better now knowing that as Dr. Boom he is no longer around to terrorize us!\n\nJust let this be a lesson to you.  Don't come down here without a nether helmet!\n\nNow, how can I repay you?", sourceObjectiveStatus = "unverified-source-field" }
quests[10222] = { id = 10222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunfury Garrison", description = "After Prince Kael'thas's forces destroyed the village and imprisoned the archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very men who destroyed our village and slew our fellows toast their 'amazing victory' while we are helpless to avenge the fallen.\n\nWe must not allow these crimes to go unanswered! Be the instrument of our vengeance, {name}. Go to Sunfury Hold and claim the lives of those responsible for this crime.", sourceObjective = "Custodian Dieworth at Kirin'Var Village wants you to kill 10 Sunfury Archers.", progress = "Is it done, {name}? Have you avenged the fallen of Kirin'Var Village?", completion = "What you've done this day can never bring back the fallen, but perhaps it can help soothe their spirits. Although, truth be told, no amount of blood can quench my anger over the actions of Kael'thas.", sourceObjectiveStatus = "unverified-source-field" }
quests[10223] = { id = 10223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down With Daellis", description = "I'll never forget the blood elf who led the attack. He wore a tabard with a device I've never seen before, over top of crimson armor.\n\nHe was ferocious and merciless, leading from the front where most other blood elf officers would never be seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn't linger long at Sunfury Hold. Kael'thas has ordered him to Manaforge Duro to aid in their attempt to control the area. Find him, {name}, and silence his bow for good.", sourceObjective = "Custodian Dieworth at Kirin'Var Village wants you to kill Master Daellis Dawnstrike.", progress = "Have you finished the task, {name}?", completion = "<You're not certain, but it seems as though Custodian Dieworth is on the verge of tears.>\n\nAt last, it is through. If I could will myself out of existence, I would, but the truth is I don't know how to let go. For the ones in the village, it is difficult but straightforward. I suppose this is the price we pay for retaining such strong ties to this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10224] = { id = 10224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence for the Engines", description = "As the X-52's chief of engineering, I have to see to it that the nether-rocket's main engines are in tip-top shape.\n\nUnfortunately, I haven't built them yet.\n\n{class}, I'm in dire straits here!  I have almost all of the parts.  All that I'm missing is the engine core.\n\nLuckily for us, I think we can make use of the essence from the local mana wraiths to jump-start the engines.\n\nThey can be found near most of the glowing trenches in the northern part of the island.  Except for here in Area 52, of course.", sourceObjective = "Collect 7 Mana Wraith Essences and return them to Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "You have all of those essences yet?", completion = "Wow, that's a lot of essence!\n\nOk, let's see what happens when I mix it with the etherlithium matrix crystals.", sourceObjectiveStatus = "unverified-source-field" }
quests[10225] = { id = 10225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Engineering", description = "{name}!  I need you to take all of these etherlithium crystals over to Chief Engineer Trep, my, uh, chief of engineering.\n\nHe should know what to do with them.  And if he doesn't, you see to it that he finds out!", sourceObjective = "Deliver the Etherlithium Matrix Crystals to Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "Um, hi.   I'm a little busy here.  What's that you have there?", completion = "Ooh, etherlithium matrix crystals.  Yeah, those sound important!\n\nLet's just put them over here and I'll get to figuring them out in a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[10226] = { id = 10226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Power Extraction", description = "Darn it, that didn't do it!\n\nOk, I've got another idea!  I had Xyrol whip up an elemental power extractor.  I'm not certain exactly what this power will do, but I know that I can use it.\n\nThe sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south have just what I need for the engines!\n\nThe extractor will change the form of their power into something solid that you'll be able to gather up after you've defeated them.", sourceObjective = "Extract 5 Elemental Power for Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "You have the power from those elementals yet?  Oh, don't hurry or anything.  It's just my life and career on the line.", completion = "That's more like it!  Alright, now I think we're in business.\n\nJust let me dump this stuff into the thing-a-ma-jig here and I'm sure it'll spit out a fully functioning phase engine core.\n\nOh, hey, I guess I ought to reward you for saving my neck!  Hehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10227] = { id = 10227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I See Dead Draenei", description = "I see dead draenei. They're all around us.\n\nBah, nobody believes me because I'm a child. Not even my own mommy believes me.\n\n<Ha'lei points to Ramdor.>\n\nHe believes me, though... He sees them too. Boy does he get angry about it!\n\nIt's kind of funny. I see ghosts and people just smile and pat me on the head, trying to placate me. Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up!\n\nYou should probably talk to Ramdor before you go inside. He was once a death priest.", sourceObjective = "Speak to Ramdor the Mad, standing on the bone pile outside of the Auchenai Crypts.", completion = "The child is correct. I was once a \"death priest.\"\n\n<Ramdor winces.>\n\nSuch an unsavory title.\n\nThrough that corridor lies the Auchenai Crypts. Inside you will find the remnants of my priory. They are all mad now, of course. Insane to the last! I suppose I stood out, being the last one among them with any common sense. Of course, I was excommunicated for my beliefs.\n\nWhat are my beliefs, you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[10228] = { id = 10228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ezekiel", description = "I believe that the dead, which we have been caring for these last 500 odd years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of Remembrance to start his experiments... Necromancy.\n\nI hope you weren't thinking about going in there... Not before helping me out so that these damned spirits will finally leave me alone. I know where they keep their treasures, {race}. Got your attention, eh?\n\nBring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.", sourceObjective = "Find and speak with Ezekiel of Shattrath in Shattrath City.", completion = "Book of the dead? Never heard of it... What's this about anyway? Who sent you?", sourceObjectiveStatus = "unverified-source-field" }
quests[10229] = { id = 10229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decipher the Tome", description = "This tome appears to be some sort of history written in a secret Alliance cipher.  Althen, the historian in Spinebreaker Post, has studied the Unyielding for some time; he may be able to crack the Alliance code and decipher the book.", sourceObjective = "Take the Mysterious Tome to Althen the Historian in Spinebreaker Post.", progress = "What is this?  A book carried by an Unyielding spirit?  How strange.  Let me study it.  Perhaps I can learn the history of the Unyielding.", completion = "I have studied ancient history my entire un-life.  I have never seen anything like this book.  It tells the entire history of the Armory, including events that happened after its destruction.  \n\nThe Unyielding have kept their history, even after they had fallen in battle.  With this book we will be able to understand the Unyielding and convince them to join us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10230] = { id = 10230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Horn", description = "Perhaps we have taken the wrong approach to the Unyielding? \n\nThe tome tells me the Expedition Armory was destroyed by orcs and death knights long ago.  The Unyielding remain here as vengeful spirits trapped in an eternal battle against the fel orc clans.  \n\nThey think only of revenge.  We must arrange for them to defeat their most hated enemies.  Enter the Expedition Armory once again and find Lieutenant Commander Thalvos.  He carries a battle horn that can summon the Unyielding.  Bring it to me.", sourceObjective = "Take the Unyielding Battle Horn from Lieutenant Commander Thalvos and bring it to Althen the Historian in Spinebreaker Post.", progress = "We must help the Unyielding soon.  If we can convince them to join us the Horde will have gained a powerful ally.", completion = "You have done well {name}.  This ancient horn will allow us to summon the Unyielding. \n\nThat is, if they are willing.", sourceObjectiveStatus = "unverified-source-field" }
quests[10231] = { id = 10231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Book? I Don't See Any Book.", description = "Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the book. Not anymore, anyway. It was stolen. Probably by one of those filthy refugees.\n\nBesides, Auchindoun is now defunct. We have no use for the book. If you find it, you can keep it.\n\nLike I said, I saw some of those ruffians snooping around the terrace last week. Start your search with them. They're probably playing dice in the slums.", sourceObjective = "Ezekiel said the book has been stolen. Your best bet is to find the Ruffians and see if they have any information.", progress = "Whaddya want?", completion = "Ok, ok! Don't hurt us. We had the book but we sold it...", sourceObjectiveStatus = "unverified-source-field" }
quests[10232] = { id = 10232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In A Scrap With The Legion", description = "The Burning Legion has moved in on our claim at the Scrap Field down the path and across the bridge to the east.\n\nThis could be a huge problem for us!  With the Legion at the Arklon Ruins, and now there, it's starting to look bad for us - and the rocket project - here at Area 52.\n\n{name}, I need you to go out there and deal with those demons!  I'd do it, but I'm a lover, not a fighter.\n\nYep, this is going to be trouble, I can feel it!", sourceObjective = "Kill 5 Mo'arg Doomsmiths and 15 Gan'arg Engineers. Then return to Papa Wheeler at Area 52 in the Netherstorm.", completion = "Well, that's good and bad news, now isn't it?  We've dealt them a blow, but with the Burning Legion running free all over the Netherstorm - and getting closer to us here - well, I don't know how it's going to go.\n\nI have a feeling that we're going to have to change gears here for a while.  Hope you'll be able to help us out, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10233] = { id = 10233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torching Sunfury Hold", description = "Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves from reoccupying it. Kael'thas's followers are zealous and tenacious. Leaving them anything to use at Sunfury is effectively an invitation to return.\n\nNo, it must all be destroyed. See to it that their tents and artillery burn to ashes!\n\n<The ghost's fists clench.>\n\nSteal torches from the Sunfury flamekeepers to accomplish your task, {name}.", sourceObjective = "Using a Flaming Torch, destroy 4 Sunfury Ballistas and 4 Sunfury Tents and return to Lieutenant-Sorcerer Morran at Kirin'Var Village.", progress = "Smoke rises from the Sunfury Hold fortifications. Is that your handiwork?", completion = "<Lieutenant-Sorcerer Morran nods grimly.>\n\nThe Kirin Tor hardly relish destruction for its own sake, but we have no qualms about acting against our enemies, even in death.", sourceObjectiveStatus = "unverified-source-field" }
quests[10234] = { id = 10234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Demon's Trash...", description = "You look like a capable young <man/woman>!  I was wondering if you could lend me a hand?\n\nTo the east is the Scrap Field, which the Burning Legion has moved into.  It's full of huge fel reaver parts.  There're also a whole bunch of smaller parts in there that they don't seem to care about.\n\nI want you to get in there and get me a lot of those smaller fel reaver parts!", sourceObjective = "Gather 10 Fel Reaver Parts and return them to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "You have those parts yet?  With the Burning Legion moving in on each of our claims around here one at a time, we unfortunately have little time.", completion = "These will have to do for now, I suppose.  If only we could scare them off.\n\nHey, that gives me an idea!", sourceObjectiveStatus = "unverified-source-field" }
quests[10235] = { id = 10235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Declawing Doomclaw", description = "You know what might just discourage them?  Take out their leader!\n\nIt seems to work everywhere else from what I've heard.  And when they see a <grizzled/tough> {class}, such as yourself take out their leader... why, I bet they'll tuck tail and run for the hills!\n\nGet back in there and take out the big one they call Doomclaw.  I hear he keeps himself in the eastern part of the Scrap Field underneath the pipe.\n\nBring me his claw, too!  Maybe we can make use of it.", sourceObjective = "Obtain Doomclaw's Hand and deliver it to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "Dealt with Doomclaw yet?", completion = "He, uh... he said what?  THEY'RE GONNA GO AFTER AREA 52?!\n\nOh, this is not good... not good!", sourceObjectiveStatus = "unverified-source-field" }
quests[10236] = { id = 10236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outland Sucks!", description = "I can't believe I left Booty Bay to come to Outland.  My cousin Screed Luckheed promised me I would make a fortune, but instead he flew off in his zeppelin and left me here to try to scrape a living out of this mine.  \n\nHow am I suppose to make a living here with helboars and demons and fel orcs attacking all the time?  My shredder here was broken yesterday and the parts I need to fix it were stolen by fel orcs.  They took the parts into the fissure to the southwest and may have dropped them there.", sourceObjective = "Find 6 Shredder Parts and return to Foreman Razelcraz by the mine northwest of Thrallmar.", progress = "Did you find some spare parts for my shredder?  I really want to get it fixed so I can get back to mining.  I have to make a living somehow, if only so I can buy a one-way ticket back to Booty Bay.", completion = "Hurray, you found some parts!  Now maybe I can get my shredder working.  If I earn enough money I might be able to get back to Booty Bay. \n\nI sure hope my cousin, Screed Luckheed, crashes that stupid zeppelin of his.  I can't believe he tricked me into coming to Outland.", sourceObjectiveStatus = "unverified-source-field" }
quests[10237] = { id = 10237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Area 52!", description = "{name}, you have to get word back to Area 52 immediately!  Hurry!\n\nTell the rocket-chief that the Burning Legion is after us now!", sourceObjective = "Deliver the bad news to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", completion = "Heh, you're kidding, right?  The Burning Legion is blaming us for all of that?\n\nBut YOU'RE the one that did it!\n\nOy, I have a headache and it's as big as this rocket.  Okay, okay, this calls for a change of plans.\n\nIf the Burning Legion thinks that it's going to come here, destroy our town and ruin my dream of cruising through the Twisted Nether, they are sadly mistaken.\n\nAnd I know just the goblin to help us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[10238] = { id = 10238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Serve Goblins", description = "Why would fel orcs steal my shredder parts?  I hate them so much.  They just sneak into my camp here and take things all the time.  A couple of days ago they stole three of my peons!  Now the rest of my peons have run off because they are afraid they are going to be eaten by fel orcs.  \n\nI can't run a mine without peons.  If you could save the peons that I lost maybe the others would come back.  The fel orcs have their camps along the wall to the southwest.", sourceObjective = "Rescue Manni, Moh and Jakk from the Fel Orc camps and return to Foreman Razelcraz by the mine northwest of Thrallmar.", progress = "Have you saved my peons yet?  Please hurry, I'm afraid they are going to be eaten and they probably won't taste very good.  If they taste really bad the fel orcs might get really mad at me.", completion = "Thank you for saving my peons.  Now maybe I can get them to fix my shredder with those parts you found, earn some money and get out of Outland.  I can't wait to be back in Booty Bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[10239] = { id = 10239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potential Energy Source", description = "We are not the only ones battling the influx of the mana beings. The blood elves, too, are troubled by them, but I'm not sure why.\n\nWhatever they're involved in over there, they don't seem to be stopping. Instead, I've seen them employ a variety of methods to kill the creatures. The most effective involves magical defenses fueled by some sort of concentrated energy.\n\nCapture some of these energy sources and bring them to me. Don't hesitate to stymie the elves if an opportunity presents itself.", sourceObjective = "Lieutenant-Sorcerer Morran at Kirin'Var Village wants you to capture 10 Energy Isolation Cubes from the blood elf operations at Manaforge Coruu.", progress = "Were you able to gather any of their energy sources?", completion = "<Morran gingerly handles one of the containers.>\n\nI don't believe I've seen anything like this before. There's certainly a lot of energy suspended in here, but it's in a raw form. We'll have to be careful with it, but I think we can find a way to adapt this to help ward off the mana creatures.", sourceObjectiveStatus = "unverified-source-field" }
quests[10240] = { id = 10240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building a Perimeter", description = "We are prepared to try to construct a perimeter around the village using the energy source taken from the blood elves. I can't guarantee that it will work, but we have to attempt it.\n\nOtherwise, the mana creatures will surely continue devouring the spirits of the fallen Kirin Tor.\n\nUse this device at the small runes around the perimeter of town to release the energy there. If I've woven the field correctly, we should start noticing a difference once you've used the device at each point.", sourceObjective = "Use the Rune Activation Device near the East Rune, Northeast Rune, and West Rune. The runes can be found around the perimeter of Kirin'Var Village's Wizard Row and Town Square districts. Return to Lieutenant-Sorcerer Morran once you've completed the task.", progress = "Have you activated all the runes? I'm eager to see if we can't improve upon the blood elf method here. Anything one of Kael'thas's men can do, real Kirin Tor can do better.", completion = "Excellent work. Keep your fingers crossed, {name}. I'm going to activate the shield.", sourceObjectiveStatus = "unverified-source-field" }
quests[10241] = { id = 10241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distraction at Manaforge B'naar", description = "We were sent here by the Sha'tar to investigate the manaforges that Kael'thas' army is operating here.  Unfortunately, the Scryers threaten to renege on their information-gathering duties unless we support them with military action.\n\nWe can't afford to compromise this mission over politics, so we've agreed to weaken the manaforge's defenses so that the Scryers can do their work.\n\nProve your loyalty to the Aldor and slay the Sunfury magisters and bloodwarders that guard Manaforge B'naar.", sourceObjective = "Slay 8 Sunfury Magisters and 8 Sunfury Bloodwarders and return to Exarch Orelis at Area 52.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Have you completed your task, {name}?", completion = "Excellent work, {name}.  The Scryers have uncovered valuable information thanks to your distraction.  Maybe they'll actually share it with us this time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10242] = { id = 10242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinebreaker Post", description = "{name}, my equipment here is, unfortunately, not configured for all the tests I'd like to perform.  However, my colleague at Spinebreaker Post, Apothecary Albreck, possesses the required implements.\n\nI have acquired a sample of Bleeding Hollow blood -- gained from a past mission of Thrallmar's agents.  Take the sample to Albreck and allow him to study it.\n\nTo reach Spinebreaker Post, speak with Wing Commander Brack, near the wyverns to the south.", sourceObjective = "Apothecary Zelana at Reaver's Fall wants you to speak with Wing Commander Brack to take a wyvern to Spinebreaker Post, and then bring the Bleeding Hollow Blood Sample to Apothecary Albreck at Spinebreaker Post.", progress = "Welcome to Spinebreaker Post.  How might my talents serve you?", completion = "A blood test, is it?  It will be my pleasure.  I always enjoy working with blood...", sourceObjectiveStatus = "unverified-source-field" }
quests[10243] = { id = 10243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naaru Technology", description = "The Scryers obtained a personnel roster for Manaforge B'naar and are now having a field day picking out assassination targets.\n\nThey've missed one small bit of information, scribbled on the side of the roster.  It appeared to be a password or code like those used to access naaru-made technology like the Exodar or Tempest Keep.\n\nGo inside the manaforge and look for a control panel.  Copy its readouts on this scroll as well as you can.  We must confirm our suspicions about the origin of the technology.", sourceObjective = "Go inside Manaforge B'naar and find the B'naar Control Console.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "The symbols scrolling in front of you look alien and unintelligible.", completion = "You unwrap the scroll and ready yourself to copy down the strange symbols.", sourceObjectiveStatus = "unverified-source-field" }
quests[10244] = { id = 10244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "R.T.F.R.C.M.", description = "Cracking the seal on this rather large tome, you can't quite make out what the words say.  They appear to be written in the language of demons.\n\nHowever, you can make out the pictures, which tell their own story.\n\nThis is clearly a fel reaver construction manual, and you know for a fact that Mama Wheeler will want to take a look at it!", sourceObjective = "Take the Fel Reaver Construction Manual to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10245] = { id = 10245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "B'naar Console Transcription", description = "You try to transcribe the shapes as you see them flash across your eyes.  The results are less than exact, but should serve as adequate evidence to prove or disprove the Aldor's suspicions.", sourceObjective = "Deliver the B'naar Console Transcription to Anchorite Karja at Area 52 in Netherstorm.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Let us see what you've brought to us, {name}.", completion = "You've done well, {name}.  Allow me a few moments to go over your transcription.\n\nYou have the priesthood's thanks, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10246] = { id = 10246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Manaforge Coruu", description = "Your success at Manaforge B'naar was quite noteworthy.  I'm sure that Anchorite Karja will ask you for a repeat performance at Manaforge Coruu next.\n\nWe've learned of a particularly important regiment of Sunfury arcanists and researchers being deployed there and I would like you to target them.  Succeed and you will deliver a crushing blow against our enemy's forces.", sourceObjective = "Travel to Manaforge Coruu and slay 8 Sunfury Arcanists and 5 Sunfury Researchers. Return to Exarch Orelis when you've completed this task.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Excellent job, {name}.  With your dedication we're sure to defeat our enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10247] = { id = 10247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doctor Vomisa, Ph.T.", description = "On the outskirts of town to the east are the Proving Grounds.  Our top experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, ethereal, and of course, goblin technologies there.\n\nThis is in no small part thanks to your gathering efforts Junior Technician 3rd Grade, {name}!\n\nGo to him; I know that he'll have a solution for saving Area 52.\n\nAnd since he's likely to use you as a test subject, if I were you, I'd bring some friends along just in case.", sourceObjective = "Speak with Doctor Vomisa, Ph.T. at the Proving Grounds in Netherstorm.", completion = "Well, well, it would appear that we are in luck, young man.\n\nI was just recently able to finish the construction of my latest invention, the Scrap Reaver X6000!\n\nAnd you're going to have the honor of helping me test it so that it can be used in defense of Area 52!", sourceObjectiveStatus = "unverified-source-field" }
quests[10248] = { id = 10248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You, Robot", description = "Doctor Vomisa, Ph.T. at your service.  Here, take this controller.  I want you to activate it and give my newly-invented Scrap Reaver X6000 a spin.\n\nJust stay nearby!  The controller is tied to my console here, and if you get too far away, the robot will cease to function.\n\nTry out everything... I'll be watching and calibrating its servos based upon your test run.", sourceObjective = "Activate the Scrap Reaver X6000 Controller and test out its capabilities. Then give your feedback to Doctor Vomisa, Ph.T at the Proving Grounds in the Netherstorm. Deal with any problems that arise.", progress = "What did you think?  Still needs some tweaking, eh?", completion = "Well, my boy that certainly was exciting!  And for my money, I'd say that the Scrap Reaver X6000 performed admirably, despite its rookie pilot.\n\nHehe, no, don't take offense, I was just kidding.  After all, you just saved Area 52 and the X-52 Nether-Rocket from certain doom!", sourceObjectiveStatus = "unverified-source-field" }
quests[10249] = { id = 10249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Chief!", description = "I'm certain that the rocket-chief is going to want to have a word or two with you!\n\nIf I were you, I wouldn't hesitate to get back to Area 52 and speak with him!", sourceObjective = "Report to Rocket-Chief Fuselage at Area 52 in the Netherstorm immediately!", completion = "{name}!  Or, should I say Junior Technician 1st Grade {name}?!  Oh hell, who am I kidding?  Skipping a grade isn't a good enough reward for what you've done.  I'm going to make you my first officer!\n\nYou've saved all of us, and more importantly the X-52 Nether-Rocket!  I could just kiss you... but I won't.\n\nInstead, please let me present you with the gratitude of Area 52.  Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[10250] = { id = 10250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Vengeance", description = "East of here is an old destroyed Alliance siege tower.  Now scavengers loot it for old nails and bits of scrap.  Long ago, many Alliance warriors lost their lives at this tower and their banner was captured by Urtrak, a foul orc commander.\n\nBlow the Unyielding battle horn near the Alliance banner.  This will get the attention of Urtrak.  It may also summon forth warriors who fell in battle long ago.", sourceObjective = "Blow the Unyielding Battle Horn near the Alliance Banner. Kill Urtrak and then return to Althen the Historian at Spinebreaker Post.", progress = "Have you blown the horn by the siege tower yet?  We must do this soon.  Who knows when Thrallmar will have need of the Unyielding.", completion = "I am glad to hear that the Unyielding joined you in your battle.  I thought they might come to the sound of their own battle horn, but I could not be sure.  Perhaps we have given some of them the vengeance they so desperately crave.  \n\nYou have slain Urtrak and we must report your victory to Commander Hogarth in the Expedition Armory.  He will understand the risks you have taken on his behalf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10251] = { id = 10251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Grand Design?", description = "A couple of draenei paid us a visit last night. They'd somehow learned that we had the book in our possession and made a very generous offer to \"take it off our hands.\"\n\nWe didn't ask them what they wanted with the book but the young one kept talking about \"the master's grand design,\" whatever that means.\n\nLook, I don't ask questions when money is in play. They gave us a lot of gold and we gave them the book.\n\nHe said that they lived in Nagrand - in the old Abandoned Armory, north of Telaar.", sourceObjective = "Find Nitrin the Learned at the Abandoned Armory in Nagrand.", completion = "The signs were all there but I turned a blind eye.\n\nThe Legion's grasp grows stronger every day. Even in these parts...\n\nHad I known... Had I known that my boy was communing with demons... They offered him power and then gave him a taste of that power. That was all that it took...\n\nThe book is gone. Taken by Levixus... His plans are known only to me and his dark master.\n\nStranger, I don't know if you've ever done right in your life, but know this: the boy must be stopped.", sourceObjectiveStatus = "unverified-source-field" }
quests[10252] = { id = 10252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision of the Dead", description = "It has already begun. Levixus stands atop the ruins of Auchindoun and reads from the book of the dead. He calls the dead out by name and, through demonic ritual, binds the tortured souls to his will. He will raise all of Auchindoun if given the chance!\n\nBut... you must first prepare. You cannot do battle with that which you cannot see.\n\n<Nitrin hands you a parchment.>\n\nBring me the items I require to brew the tincture. It will open your mind and allow you to see into the spirit world.", sourceObjective = "Nitrin at the Abandoned Armory in Nagrand wants you to bring him 1 Mountain Gronn Eyeball, 1 Flawless Greater Windroc Beak, and 1 Aged Clefthoof Blubber.", progress = "Levixus's army grows in size and power with each second that passes. You must hurry.", completion = "Stranger... I was not forthright with you. Once you drink this potion, you will forever see into the world of the dead. This recipe that you drink of is a rite of initiation for all death priests of Auchindoun. Many go mad after its effects have taken hold. Seeing the dead is ... shocking.\n\n<Nitrin puts the potion up to your lips.>\n\nDo you wish to continue?", sourceObjectiveStatus = "unverified-source-field" }
